// Versículos do dia: 365 entradas, uma para cada dia do ano (ordem canônica).
// Texto bíblico: João Ferreira de Almeida. Cada item traz o contexto histórico em que
// o versículo foi escrito e legendas de pesos, medidas e geografia citados no texto.
const VERSICULOS = [
{ r: "Gênesis 1:1", t: "No princípio criou Deus os céus e a terra.",
    c: "Versículo que abre a Bíblia. Israel acabara de sair do Egito, onde se adoravam muitos deuses ligados ao sol e ao Nilo. O texto afirma que um único Deus criou tudo pela sua palavra.",
    l: ["“Céus e terra” é uma expressão hebraica que designa o universo inteiro.",
        "Os povos da Mesopotâmia contavam a criação como luta entre deuses; Gênesis apresenta um só Criador."] },
  { r: "Gênesis 1:27", t: "E criou Deus o homem à sua imagem; à imagem de Deus o criou; homem e mulher os criou.",
    c: "Escrito por Moisés para os israelitas recém-saídos do Egito, o relato afirma a dignidade de todo ser humano, contra a ideia de que só os reis eram imagem dos deuses.",
    l: ["“Imagem” traduz o hebraico tselem, usado no Oriente Antigo para estátuas de reis colocadas em templos.",
        "Diferente dos monarcas, aqui todos os seres humanos, homem e mulher, são imagem de Deus."] },
  { r: "Gênesis 2:7", t: "E formou o SENHOR Deus o homem do pó da terra, e soprou em suas narinas o fôlego da vida; e o homem foi feito alma vivente.",
    c: "Segundo relato da criação, voltado ao homem e ao jardim, ensinava Israel que a vida é dada por Deus, e não resultado de forças impessoais.",
    l: ["“Pó da terra” refere-se ao solo cultivável, de onde vem o nome hebraico adam.",
        "“Fôlego da vida” indica que a vida humana não existe por si, mas é concedida por Deus."] },
  { r: "Gênesis 2:24", t: "Portanto, deixará o varão o seu pai e a sua mãe, e apegar-se-á à sua mulher, e serão ambos uma carne.",
    c: "Texto que fundamenta a família em Israel, povo cuja vida social se organizava pela casa e pelo casamento, base da transmissão da aliança.",
    l: ["O verbo “apegar-se” expressa a aliança leal que liga o casal.",
        "“Uma carne” descreve a união plena do marido e da mulher, base citada por Jesus e por Paulo."] },
  { r: "Gênesis 3:15", t: "E porei inimizade entre ti e a mulher, e entre a tua semente e a sua semente; esta te ferirá a cabeça, e tu lhe ferirás o calcanhar.",
    c: "Narração da queda, quando a serpente engana a mulher; a promessa de vitória da semente da mulher sustentava a esperança de Israel.",
    l: ["“Ferir o calcanhar” e “ferir a cabeça” descrevem golpes desiguais: o da semente da mulher seria decisivo.",
        "A serpente era, no antigo Oriente, símbolo ligado à fertilidade e à magia, aqui apresentada como inimiga de Deus."] },
  { r: "Gênesis 6:8", t: "Mas Noé achou graça aos olhos do SENHOR.",
    c: "No tempo de Noé, a corrupção da humanidade levara Deus ao juízo; a graça concedida a um justo preservou a vida sobre a terra.",
    l: ["“Achar graça aos olhos” é expressão hebraica que indica favor concedido por um superior.",
        "O nome Noé liga-se ao hebraico noach, associado à ideia de repouso e consolação."] },
  { r: "Gênesis 8:22", t: "Enquanto a terra durar, sementeira e sega, e frio e calor, e verão e inverno, e dia e noite, não cessarão.",
    c: "Depois do dilúvio, Deus promete estabilidade ao mundo criado, garantindo à humanidade as condições para recomeçar.",
    l: ["“Sementeira e sega” referem-se ao ciclo agrícola, base da vida no antigo Israel.",
        "“Verão e inverno” indica as duas grandes estações da região, o tempo seco e o das chuvas."] },
  { r: "Gênesis 9:13", t: "O meu arco tenho posto nas nuvens; este será por sinal do concerto entre mim e a terra.",
    c: "Pacto de Deus com Noé e com toda a criação após o dilúvio, sinal de que o mundo não seria novamente destruído pelas águas.",
    l: ["O arco nas nuvens é o arco-íris, chamado “arco” como o instrumento de guerra que Deus depõe.",
        "“Concerto” traduz o hebraico berith, termo de aliança usado entre reis e servos no Oriente Antigo."] },
  { r: "Gênesis 12:2", t: "E far-te-ei uma grande nação, e abençoar-te-ei, e engrandecerei o teu nome; e tu serás uma bênção.",
    c: "Chamado de Abrão em Harã, quando Deus promete fazer dele uma grande nação, origem do povo de Israel.",
    l: ["“Engrandecer o nome” referia-se à fama e à honra de um clã no mundo antigo.",
        "Harã ficava no norte da Mesopotâmia, ponto de rotas de comércio entre a Babilônia e o Levante."] },
  { r: "Gênesis 15:6", t: "E creu ele no SENHOR, e imputou-lhe isto a justiça.",
    c: "Abrão, ainda sem filhos, recebe a promessa de descendência numerosa; sua fé é contada como justiça diante de Deus.",
    l: ["“Imputar” é termo contábil: a justiça lhe é creditada como numa conta.",
        "A fé de Abrão é citada por Paulo e por Tiago no Novo Testamento como exemplo de justificação."] },
  { r: "Gênesis 18:14", t: "Haveria coisa alguma difícil ao SENHOR? Ao tempo determinado, tornarei a ti por este tempo da vida, e Sara terá um filho.",
    c: "Visitantes anunciam a Abraão e Sara que, já na velhice, teriam um filho, confirmando a promessa feita em Harã.",
    l: ["“Tempo determinado” indica a época fixada por Deus, ligada ao retorno da visita.",
        "Sara já não tinha idade para conceber, o que realçava o caráter sobrenatural da promessa."] },
  { r: "Gênesis 22:8", t: "E disse Abraão: Deus proverá para si o cordeiro, meu filho. Assim caminharam ambos juntos.",
    c: "Subida ao monte Moriá para o sacrifício de Isaque; a resposta de Abraão apontava para o provimento de Deus.",
    l: ["“Cordeiro” designa o animal usado em sacrifícios, oferecido em lugar do primogênito.",
        "O monte Moriá, na região de Jerusalém, ficou ligado, na tradição, ao lugar do templo."] },
  { r: "Gênesis 28:15", t: "E eis que estou contigo, e te guardarei por onde quer que fores, e te farei tornar a esta terra, porque não te deixarei, até que haja cumprido o que te tenho falado.",
    c: "Jacó, fugindo de Esaú, sonha em Betel; Deus renova a promessa feita a Abraão e a Isaque.",
    l: ["Betel, a “casa de Deus”, ficava ao norte de Jerusalém, na rota montanhosa central de Canaã.",
        "“Te guardarei” indica proteção na viagem, em tempo em que caminhar por terras estrangeiras era perigoso."] },
  { r: "Gênesis 32:28", t: "Então, disse: Não será mais o teu nome Jacó, mas Israel, porque, como príncipe, lutaste com Deus e com os homens, e prevaleceste.",
    c: "Jacó luta no vau do Jaboque e recebe o nome Israel, que passou a designar o povo da aliança.",
    l: ["“Israel” relaciona-se ao hebraico que significa “lutar com Deus”.",
        "O vau do Jaboque, afluente do Jordão, era ponto de travessia usado por pastores e caravanas."] },
  { r: "Gênesis 39:2", t: "E o SENHOR estava com José, e foi homem próspero, e estava na casa de seu senhor egípcio.",
    c: "José, vendido como escravo, serve na casa de Potifar no Egito; a narrativa mostra que Deus permanecia com ele no cativeiro.",
    l: ["“Egípcio” lembra que José vivia em terra estrangeira, longe de Canaã.",
        "O Egito era a grande potência agrícola da época, cuja economia dependia em parte de escravos."] },
  { r: "Gênesis 45:5", t: "Agora, pois, não vos entristeçais, nem vos pese aos vossos olhos por me haverdes vendido para cá; porque para conservação da vida, Deus me enviou diante da vossa face.",
    c: "José revela-se aos irmãos no Egito e interpreta sua venda como providência de Deus para salvar a família da fome.",
    l: ["“Conservação da vida” refere-se ao plano de Deus de manter vivo o povo por meio do alimento.",
        "A fome que atingiu a região levou muitos hebreus a descer ao Egito em busca de trigo."] },
  { r: "Gênesis 49:10", t: "O cetro não se arredará de Judá, nem o legislador dentre seus pés, até que venha Siló; e a ele se congregarão os povos.",
    c: "Bênção profética de Jacó sobre Judá, apontando o futuro domínio da tribo e a vinda do Messias.",
    l: ["“Cetro” era a vara de comando dos reis, símbolo de autoridade.",
        "“Siló” é termo de sentido debatido; a tradição cristã o leu como referência ao Messias."] },
  { r: "Gênesis 50:20", t: "Vós, na verdade, intentastes o mal contra mim; porém Deus o tornou em bem, para fazer, como vedes agora, que se conserve muita gente em vida.",
    c: "José, já governador no Egito, consola os irmãos após a morte de Jacó, resumindo o propósito de Deus na história.",
    l: ["“Intentastes o mal” refere-se à venda de José, feita por inveja.",
        "“Conservar muita gente em vida” aponta a fome da época, quando José armazenou trigo para todos."] },
  { r: "Êxodo 3:14", t: "E disse Deus a Moisés: EU SOU O QUE SOU. Disse mais: Assim dirás aos filhos de Israel: EU SOU me enviou a vós.",
    c: "Moisés, pastoreando em Midiã, é chamado por Deus na sarça ardente para libertar Israel do Egito.",
    l: ["“EU SOU O QUE SOU” traduz o hebraico ehyeh asher ehyeh, ligado ao nome divino YHWH.",
        "Midiã ficava a leste do golfo de Acaba, região desértica onde Moisés vivera como pastor."] },
  { r: "Êxodo 6:7", t: "E eu vos tomarei por meu povo, e serei vosso Deus; e sabereis que eu sou o SENHOR vosso Deus, que vos tiro de debaixo das cargas dos egípcios.",
    c: "Deus reafirma a Moisés que tiraria Israel do Egito e o tomaria por povo seu, em meio ao duro cativeiro.",
    l: ["“Debaixo das cargas” descreve a servidão dos hebreus nas obras de tijolos do Egito.",
        "“Tomarei por meu povo” emprega linguagem de aliança, comum em tratados do antigo Oriente."] },
  { r: "Êxodo 12:13", t: "E o sangue vos será por sinal nas casas em que estiverdes; vendo eu o sangue, passarei por cima de vós, e não haverá entre vós praga de mortandade, quando eu ferir a terra do Egito.",
    c: "Instituição da Páscoa, na noite da libertação, quando o sangue do cordeiro marcava as casas dos israelitas.",
    l: ["O sangue nas portas era sinal visível da aliança e da proteção de Deus.",
        "“Passarei por cima” deu nome à Páscoa, ligada ao verbo hebraico pasach, “passar por cima”."] },
  { r: "Êxodo 13:21", t: "E o SENHOR ia adiante deles, de dia numa coluna de nuvem, para os guiar pelo caminho, e de noite numa coluna de fogo, para os alumiar, para que caminhassem de dia e de noite.",
    c: "Após saírem do Egito, os israelitas marchavam para o deserto guiados pela presença visível de Deus.",
    l: ["A coluna de nuvem e de fogo conduzia um povo em peregrinação, sem rota fixa.",
        "O deserto de Sur, primeira etapa após o mar, faz parte da península do Sinai."] },
  { r: "Êxodo 14:14", t: "O SENHOR pelejará por vós, e vós vos calareis.",
    c: "No mar Vermelho, cercado pelo exército de Faraó, Israel ouve de Moisés que Deus pelejaria por ele.",
    l: ["“Pelejará por vós” indica guerra santa, em que Deus é o guerreiro e o povo apenas observa.",
        "O mar Vermelho, ou mar de Juncos, situa-se entre o Egito e a península do Sinai."] },
  { r: "Êxodo 15:2", t: "O SENHOR é a minha força e o meu cântico, porque ele me salvou; este é o meu Deus, portanto o louvarei; ele é o Deus de meu pai, por isso o exaltarei.",
    c: "Cântico de Moisés e dos israelitas após a travessia do mar, primeira grande canção de louvor de Israel.",
    l: ["“Força” e “cântico” traduzem termos hebraicos de exaltação usados em hinos de vitória.",
        "O cântico celebra o triunfo sobre carros e cavaleiros do Egito, símbolo do poderio militar."] },
  { r: "Êxodo 16:4", t: "Então, disse o SENHOR a Moisés: Eis que vos farei chover pão dos céus, e o povo sairá e colherá cada dia a porção para cada dia, para que eu o prove se anda em minha lei ou não.",
    c: "No deserto de Sim, Deus dá o maná ao povo faminto, testando sua obediência diária.",
    l: ["“Pão dos céus” é o maná, alimento recolhido em porção diária, exceto antes do sábado.",
        "O deserto de Sim fica entre o mar Vermelho e o monte Sinai, região árida e sem plantio."] },
  { r: "Êxodo 19:5", t: "Agora, pois, se diligentemente ouvirdes a minha voz e guardardes o meu concerto, então, sereis a minha propriedade peculiar dentre todos os povos; porque toda a terra é minha.",
    c: "No monte Sinai, Deus propõe aliança a Israel e o chama a ser propriedade peculiar entre as nações.",
    l: ["“Propriedade peculiar” traduz o hebraico segullah, tesouro particular de um rei.",
        "O monte Sinai fica na península homônima, identificado pela tradição com o monte de Deus."] },
  { r: "Êxodo 20:3", t: "Não terás outros deuses diante de mim.",
    c: "Primeiro dos Dez Mandamentos, dados a Israel no Sinai como fundamento da aliança.",
    l: ["“Diante de mim” pode significar “além de mim” ou “na minha presença”, proibindo rivais a Deus.",
        "Os “outros deuses” eram as divindades do Egito e de Canaã, ligadas a Baal, a Astarote e ao sol."] },
  { r: "Êxodo 20:12", t: "Honra a teu pai e a tua mãe, para que se prolonguem os teus dias na terra que o SENHOR, teu Deus, te dá.",
    c: "Mandamento de honrar os pais, com promessa de vida longa na terra prometida a Israel.",
    l: ["“Honrar” implicava cuidar dos pais idosos e respeitar sua autoridade na família.",
        "“Prolongar os dias” refere-se à permanência de Israel na terra de Canaã, sob a bênção de Deus."] },
  { r: "Êxodo 24:7", t: "E tomou o livro do concerto e o leu aos ouvidos do povo, e eles disseram: Tudo o que o SENHOR tem falado faremos e obedeceremos.",
    c: "Cerimônia no Sinai em que o povo aceita solenemente o livro da aliança, selando o compromisso com Deus.",
    l: ["“Livro do concerto” era o documento com as palavras de Deus entregues a Moisés.",
        "A fórmula “faremos e obedeceremos” selava o compromisso de Israel como povo da aliança."] },
  { r: "Êxodo 25:8", t: "E me farão um santuário, e habitarei no meio deles.",
    c: "Deus ordena que se prepare o santuário, onde habitaria no meio de Israel durante a peregrinação no deserto.",
    l: ["O santuário era o tabernáculo, tenda móvel própria de um povo em viagem.",
        "“Habitar no meio” expressa a proximidade de Deus, ideia central para Israel no deserto."] },
  { r: "Êxodo 31:3", t: "E o enchi do Espírito de Deus, de sabedoria, e de entendimento, e de ciência, em todo o lavor.",
    c: "Deus capacita Bezalel com seu Espírito para os trabalhos artísticos do tabernáculo.",
    l: ["“Espírito de Deus” indica habilidade concedida para o serviço, e não apenas poder profético.",
        "“Lavor” designa o trabalho de artesanato, como o dos metais e tecidos usados no culto."] },
  { r: "Êxodo 33:14", t: "E disse: A minha presença irá contigo, e eu te darei descanso.",
    c: "Após o pecado do bezerro de ouro, Deus promete a Moisés que sua presença acompanharia o povo.",
    l: ["“Presença” remete ao rosto de Deus, linguagem ligada ao favor e à proteção divinos.",
        "“Descanso” aponta o repouso que Israel teria na terra prometida, fim da peregrinação."] },
  { r: "Êxodo 34:6", t: "E, passando o SENHOR por diante dele, clamou: SENHOR, SENHOR Deus, misericordioso e piedoso, tardio em irar-se e grande em beneficência e verdade.",
    c: "Deus proclama seu caráter a Moisés no Sinai, após renovar a aliança com Israel.",
    l: ["“Misericordioso e piedoso” traduz termos hebraicos de compaixão e favor gratuitos.",
        "“Tardio em irar-se” descreve a paciência de Deus diante da rebeldia do povo."] },
  { r: "Êxodo 35:21", t: "E veio todo o homem cujo coração o moveu, e todo aquele cujo espírito o fez voluntário, e trouxe a oferta alçada do SENHOR, para a obra do tabernáculo da congregação, e para todo o seu ministério, e para as vestes santas.",
    c: "O povo traz voluntariamente ofertas para edificar o tabernáculo, movido por coração disposto.",
    l: ["“Oferta alçada” era uma contribuição levantada diante de Deus no culto.",
        "“Tabernáculo da congregação” era a tenda onde Deus se encontrava com o povo."] },
  { r: "Êxodo 40:34", t: "Então, a nuvem cobriu a tenda da congregação, e a glória do SENHOR encheu o tabernáculo.",
    c: "Ao ser levantado o tabernáculo, a glória de Deus o enche, sinal de sua presença entre Israel.",
    l: ["“Tenda da congregação” designa o lugar oficial de encontro entre Deus e Moisés.",
        "A nuvem sobre a tenda indicava quando Israel devia partir ou acampar no deserto."] },
  { r: "Levítico 10:3", t: "Então, disse Moisés a Arão: Isto é o que o SENHOR falou, dizendo: Serei santificado naqueles que se cheguem a mim e serei glorificado diante de todo o povo. E Arão calou-se.",
    c: "Após a morte de Nadabe e Abiú por oferecerem fogo estranho, Moisés explica a santidade exigida no culto.",
    l: ["“Santificado” indica que Deus deve ser tratado com reverência por quem dele se aproxima.",
        "O fogo estranho era brasas ou incenso não prescritos pela lei do altar."] },
  { r: "Levítico 11:45", t: "Porque eu sou o SENHOR, que vos fiz subir da terra do Egito, para ser vosso Deus; portanto, vós sereis santos, porque eu sou santo.",
    c: "Regras sobre animais puros e impuros; Deus lembra a Israel que o tirou do Egito e o chama à santidade.",
    l: ["Animais “puros” eram os permitidos no culto e no consumo, conforme as listas da lei.",
        "“Santos” significa separados para Deus, em contraste com os costumes dos povos vizinhos."] },
  { r: "Levítico 16:30", t: "Porque, naquele dia, se fará expiação por vós, para purificar-vos; e sereis purificados de todos os vossos pecados perante o SENHOR.",
    c: "Instituição do Dia da Expiação, único dia em que o sumo sacerdote entrava no Santo dos Santos.",
    l: ["“Expiação” traduz o hebraico kippur, ideia de cobrir e purificar o pecado.",
        "O Dia da Expiação era o mais solene do calendário de Israel, celebrado uma vez por ano."] },
  { r: "Levítico 17:11", t: "Porque a alma da carne está no sangue, pelo que vo-lo tenho dado sobre o altar, para fazer expiação por vossas almas; porquanto é o sangue que fará expiação pela alma.",
    c: "Lei que proíbe comer sangue e ensina seu valor, porque nele está a vida oferecida no altar.",
    l: ["“A alma da carne está no sangue” reflete a visão hebraica de que a vida reside no sangue.",
        "“Expiação” liga o sangue derramado ao perdão dos pecados no culto do tabernáculo."] },
  { r: "Levítico 18:5", t: "Portanto, guardareis os meus estatutos e os meus juízos, que, fazendo-os o homem, viverá por eles. Eu sou o SENHOR.",
    c: "Chamado à obediência aos estatutos de Deus, em oposição aos costumes do Egito e de Canaã.",
    l: ["“Estatutos e juízos” são as leis morais e rituais dadas a Israel.",
        "“Viverá por eles” promete vida ao que cumpre a lei, frase citada no Novo Testamento."] },
  { r: "Levítico 19:2", t: "Fala a toda a congregação dos filhos de Israel e dize-lhes: Santos sereis, porque eu, o SENHOR, vosso Deus, sou santo.",
    c: "O capítulo reúne leis de santidade dirigidas a toda a congregação de Israel no Sinai.",
    l: ["“Santos” indica separação para Deus, base de toda a moral da lei levítica.",
        "“Congregação” designa o povo reunido em assembleia diante do tabernáculo."] },
  { r: "Levítico 19:18", t: "Não te vingarás, nem guardarás ira contra os filhos do teu povo; mas amarás o teu próximo como a ti mesmo. Eu sou o SENHOR.",
    c: "Lei do amor ao próximo, na seção que ensina a santidade nas relações sociais de Israel.",
    l: ["“Próximo” refere-se ao compatriota e ao estrangeiro residente na terra.",
        "Jesus citou este versículo como um dos dois grandes mandamentos."] },
  { r: "Levítico 20:7", t: "Portanto, santificai-vos e sede santos, pois eu sou o SENHOR, vosso Deus.",
    c: "Advertência contra os costumes de Canaã, como o culto a Moloque, e convite à santidade.",
    l: ["“Santificai-vos” é o mesmo verbo usado para separar o povo e os objetos para Deus.",
        "Moloque era divindade cananeia ligada a sacrifícios de crianças, condenados pela lei."] },
  { r: "Levítico 25:10", t: "E santificareis o ano quinquagésimo e apregoareis liberdade na terra a todos os seus moradores; ano de jubileu vos será; tornareis cada um à sua possessão, e cada um à sua família tornareis.",
    c: "Lei do jubileu, que a cada cinquenta anos devolvia as terras e libertava os escravos em Israel.",
    l: ["“Ano quinquagésimo” era o jubileu, proclamado após sete anos sabáticos.",
        "“Liberdade na terra” proclamava a volta de cada um à sua possessão e à sua família."] },
  { r: "Levítico 26:12", t: "E andarei entre vós, e eu serei o vosso Deus, e vós sereis o meu povo.",
    c: "Bênçãos da obediência, quando Deus promete habitar entre o povo e ser seu Deus.",
    l: ["“Andarei entre vós” usa imagem de caminhada íntima, como no jardim do Éden.",
        "“Serei o vosso Deus” é a fórmula da aliança repetida ao longo do Antigo Testamento."] },
  { r: "Números 6:24", t: "O SENHOR te abençoe e te guarde.",
    c: "Início da bênção que os sacerdotes deviam pronunciar sobre Israel, parte das leis do nazireado.",
    l: ["“Abençoar” e “guardar” indicam favor e proteção divinos sobre o povo.",
        "A bênção era falada pelo sacerdote no culto, no tabernáculo."] },
  { r: "Números 6:25", t: "O SENHOR faça resplandecer o seu rosto sobre ti e tenha misericórdia de ti.",
    c: "Continuação da bênção sacerdotal, em que se pede o favor e a misericórdia de Deus sobre Israel.",
    l: ["“Resplandecer o rosto” é imagem do semblante favorável de Deus voltado ao povo.",
        "A expressão equivale a conceder graça e atenção, como a de um rei a seu súdito."] },
  { r: "Números 6:26", t: "O SENHOR sobre ti levante o seu rosto e te dê a paz.",
    c: "Fecho da bênção sacerdotal, que termina pedindo paz ao povo de Israel.",
    l: ["“Levantar o rosto” indica acolhimento, e não um olhar irado.",
        "“Paz” traduz o hebraico shalom, bem-estar completo, não só ausência de guerra."] },
  { r: "Números 10:35", t: "E acontecia que, partindo a arca, Moisés dizia: Levanta-te, SENHOR, e dissipados sejam os teus inimigos, e fujam diante de ti os aborrecedores.",
    c: "Fórmula usada por Moisés quando a arca partia, nas marchas de Israel pelo deserto.",
    l: ["A arca guardava as tábuas da lei e representava a presença de Deus no meio do povo.",
        "“Levanta-te” era grito de guerra santa, convocando Deus a agir contra os inimigos."] },
  { r: "Números 11:23", t: "Então, disse o SENHOR a Moisés: Estaria o braço do SENHOR abreviado? Agora, verás se a minha palavra te acontecerá ou não.",
    c: "Deus responde à dúvida de Moisés sobre carne para o povo, mostrando que seu poder não tem limite.",
    l: ["“Braço abreviado” é imagem hebraica do poder de Deus, como de um braço forte.",
        "A cena ocorre no deserto de Parã, durante a longa peregrinação de Israel."] },
  { r: "Números 14:9", t: "Tão somente não sejais rebeldes contra o SENHOR e não temais o povo desta terra, porquanto são eles o nosso pão; retirou-se deles o seu abrigo, e o SENHOR está conosco; não os temais.",
    c: "Josué e Calebe animam o povo a crer em Deus e entrar em Canaã, apesar do medo dos demais espias.",
    l: ["“Nosso pão” é imagem que sugere que os inimigos seriam presa fácil para Israel.",
        "“Abrigo” refere-se à proteção dos deuses ou dos reis cananeus, que se retiraria deles."] },
  { r: "Números 14:18", t: "O SENHOR é longânimo e grande em benignidade, que perdoa a iniquidade e a transgressão, ainda que não inocenta o culpado, e visita a iniquidade dos pais nos filhos até à terceira e quarta geração.",
    c: "Deus proclama sua paciência e justiça após a murmuração do povo no deserto.",
    l: ["“Longânimo” significa lento para a ira, disposto a suportar.",
        "“Terceira e quarta geração” indica o alcance duradouro das consequências do pecado."] },
  { r: "Números 15:41", t: "Eu sou o SENHOR, vosso Deus, que vos tirei da terra do Egito, para vos ser por Deus; eu sou o SENHOR, vosso Deus.",
    c: "Fecho de leis sobre as borlas das vestes, que recordavam a Israel seu Deus e a saída do Egito.",
    l: ["“Tirei da terra do Egito” é a fórmula do Êxodo, base da identidade de Israel.",
        "As borlas nas vestes serviam de lembrete visível dos mandamentos de Deus."] },
  { r: "Números 20:12", t: "Depois, disse o SENHOR a Moisés e a Arão: Visto que não crestes em mim, para me santificardes diante dos filhos de Israel, por isso não metereis esta congregação na terra que lhes tenho dado.",
    c: "Em Meribá, Moisés fere a rocha em vez de falar, e Deus anuncia que ele não entraria em Canaã.",
    l: ["“Não crestes” aponta a falta de fé de Moisés e Arão diante do povo.",
        "Cades, no deserto de Zim, era o oásis onde Israel acampou por longo tempo."] },
  { r: "Números 21:9", t: "E Moisés fez uma serpente de metal e pôs-lhe sobre uma haste; e era que, mordendo alguma serpente a alguém, olhava para a serpente de metal e ficava vivo.",
    c: "No deserto, mordidos por serpentes, os israelitas eram curados ao olhar para a serpente de metal erguida por Moisés.",
    l: ["A serpente de metal, feita de bronze, ficou guardada por Israel como objeto de culto.",
        "Jesus comparou esta serpente erguida à sua própria crucifixão."] },
  { r: "Números 23:19", t: "Deus não é homem, para que minta; nem filho do homem, para que se arrependa. Porventura, tendo ele dito, não o fará? Ou, havendo falado, não o cumprirá?",
    c: "Balaão, contratado para amaldiçoar Israel, declara que Deus não mente nem muda de propósito.",
    l: ["“Filho do homem” significa aqui simples ser humano, sujeito a erro.",
        "Balaão era vidente da região do Eufrates, chamado por Balaque, rei de Moabe."] },
  { r: "Números 24:17", t: "Vê-lo-ei, mas não agora; contemplá-lo-ei, mas não de perto; uma estrela procederá de Jacó, e um cetro subirá de Israel, que ferirá os termos dos moabitas e destruirá todos os filhos de Sete.",
    c: "Oráculo de Balaão sobre a estrela e o cetro que surgiriam de Jacó, lido como promessa messiânica.",
    l: ["“Estrela” e “cetro” simbolizam um rei, imagem comum nas profecias do antigo Oriente.",
        "“Filhos de Sete” é designação antiga de povos, aqui tomada como os inimigos de Israel."] },
  { r: "Números 32:23", t: "Mas, se assim não fizerdes, eis que haveis pecado contra o SENHOR; e sabei que o vosso pecado vos há de achar.",
    c: "Moisés adverte as tribos de Rúben e Gade sobre as consequências de não cumprirem sua promessa.",
    l: ["“Vos há de achar” indica que o pecado não fica impune, mas alcança o culpado.",
        "As tribos pediam terras a leste do Jordão, na região de Gileade."] },
  { r: "Deuteronômio 4:29", t: "Então, dali buscarás ao SENHOR, teu Deus, e o acharás, quando o buscares de todo o teu coração e de toda a tua alma.",
    c: "Moisés fala às novas gerações de Israel nas campinas de Moabe, antes da entrada em Canaã.",
    l: ["“De todo o teu coração” indica busca sincera, e não meramente ritual.",
        "As campinas de Moabe ficavam a leste do Jordão, defronte de Jericó."] },
  { r: "Deuteronômio 5:16", t: "Honra a teu pai e a tua mãe, como o SENHOR, teu Deus, te ordenou, para que se prolonguem os teus dias e para que te vá bem na terra que te dá o SENHOR, teu Deus.",
    c: "Repetição do mandamento de honrar os pais, no segundo discurso de Moisés ao povo.",
    l: ["“Honra” implicava cuidado e respeito pelos pais, base da vida familiar em Israel.",
        "“Prolonguem os teus dias” liga a obediência à permanência na terra prometida."] },
  { r: "Deuteronômio 6:5", t: "Amarás, pois, o SENHOR, teu Deus, de todo o teu coração, e de toda a tua alma, e de todo o teu poder.",
    c: "Chamado ao amor total a Deus, no texto conhecido como Shemá, recitado diariamente por Israel.",
    l: ["“Coração, alma e poder” resume as dimensões interior, vital e prática da pessoa.",
        "O Shemá é a oração central do judaísmo até hoje."] },
  { r: "Deuteronômio 6:7", t: "E as ensinarás a teus filhos e delas falarás assentado em tua casa, e andando pelo caminho, e deitando-te, e levantando-te.",
    c: "Ordem de ensinar a lei aos filhos, integrando-a à vida diária do lar e das viagens.",
    l: ["“Assentado, andando, deitando e levantando” cobre as horas do dia na casa israelita.",
        "O ensino familiar transmitia a aliança de geração em geração."] },
  { r: "Deuteronômio 7:9", t: "Saberás, pois, que o SENHOR, teu Deus, é Deus, o Deus fiel, que guarda o concerto e a misericórdia até mil gerações aos que o amam e guardam os seus mandamentos.",
    c: "Moisés lembra a Israel que Deus é fiel à aliança, ao exortá-lo a não seguir os povos de Canaã.",
    l: ["“Fiel” traduz o hebraico ne'eman, aquele em quem se pode confiar.",
        "“Mil gerações” é expressão de fidelidade que ultrapassa o tempo humano."] },
  { r: "Deuteronômio 8:3", t: "E te humilhou, e te deixou ter fome, e te sustentou com o maná, que tu não conhecias, nem teus pais o conheciam, para te dar a entender que não só de pão viverá o homem, mas de tudo o que procede da boca do SENHOR viverá o homem.",
    c: "Recordação do maná no deserto, ensinando que o homem depende da palavra de Deus.",
    l: ["O maná foi o alimento dado no deserto, desconhecido pelos pais de Israel.",
        "“Não só de pão viverá o homem” foi citado por Jesus em sua tentação."] },
  { r: "Deuteronômio 10:12", t: "Agora, pois, ó Israel, que é o que o SENHOR, teu Deus, pede de ti, senão que temas o SENHOR, teu Deus, e que andes em todos os seus caminhos, e o ames, e sirvas ao SENHOR, teu Deus, com todo o teu coração e com toda a tua alma.",
    c: "Moisés resume o que Deus pede de Israel: temor, caminho, amor e serviço de todo o coração.",
    l: ["“Temas” indica reverência e obediência, não medo servil.",
        "“Andar nos caminhos” significa seguir o modo de vida prescrito pela lei."] },
  { r: "Deuteronômio 15:11", t: "Pois nunca deixará de haver pobre na terra; pelo que te ordeno, dizendo: Livremente abrirás a tua mão para o teu irmão, para o teu necessitado e para o teu pobre na tua terra.",
    c: "Lei sobre os pobres, parte das normas sociais de Israel que regulavam as dívidas e a generosidade.",
    l: ["“Abrir a mão” é imagem de generosidade, ao contrário de fechar a mão ao necessitado.",
        "“Teu irmão” inclui o compatriota, o estrangeiro residente e o pobre da terra."] },
  { r: "Deuteronômio 18:15", t: "O SENHOR, teu Deus, te despertará um profeta do meio de ti, de teus irmãos, como eu; a ele ouvireis.",
    c: "Promessa de um profeta como Moisés, em contraste com as práticas de adivinhação dos povos vizinhos.",
    l: ["“Como eu” indica um profeta mediador, semelhante a Moisés.",
        "Pedro e Estêvão aplicaram esta promessa a Cristo no Novo Testamento."] },
  { r: "Deuteronômio 30:6", t: "E o SENHOR, teu Deus, circuncidará o teu coração e o coração de tua semente, para amares ao SENHOR, teu Deus, com todo o teu coração e com toda a tua alma, para que vivas.",
    c: "Deus promete transformar o coração do povo, para que ame e viva em obediência após o retorno à terra.",
    l: ["“Circuncidará o coração” é imagem de mudança interior, não apenas de rito externo.",
        "A promessa aponta a restauração de Israel depois do exílio."] },
  { r: "Deuteronômio 30:19", t: "Os céus e a terra tomo, hoje, por testemunhas contra ti, que te propus a vida e a morte, a bênção e a maldição; escolhe, pois, a vida, para que vivas, tu e a tua semente.",
    c: "Fecho do discurso de Moisés, que põe diante de Israel a escolha entre vida e morte, bênção e maldição.",
    l: ["“Céus e terra” tomados por testemunhas era fórmula jurídica de aliança antiga.",
        "“Escolhe a vida” convoca o povo à decisão consciente de obedecer."] },
  { r: "Deuteronômio 31:6", t: "Esforçai-vos, e animai-vos; não temais, nem vos espanteis diante deles, porque o SENHOR, teu Deus, é o que vai contigo; não te deixará nem te desamparará.",
    c: "Moisés encoraja o povo e Josué a não temerem os inimigos, pois Deus iria adiante deles na conquista.",
    l: ["“Teu Deus é o que vai contigo” retoma a promessa da presença divina na conquista.",
        "A frase foi citada na carta aos Hebreus, como consolo aos cristãos."] },
  { r: "Deuteronômio 32:4", t: "Ele é a Rocha cuja obra é perfeita, porque todos os seus caminhos juízo são; Deus é a verdade, e não há nele injustiça; justo e reto é.",
    c: "Início do cântico de Moisés, que proclama a fidelidade e a justiça de Deus diante de Israel.",
    l: ["“Rocha” é um dos títulos de Deus, imagem de firmeza e proteção.",
        "“Justo e reto” descreve o caráter moral de Deus, base de seus juízos."] },
  { r: "Deuteronômio 33:27", t: "O eterno Deus é o teu refúgio, e debaixo de ti estende os braços eternos; e ele expulsará os inimigos de diante de ti, e dirá: Destrói-os.",
    c: "Bênção final de Moisés sobre as tribos, assegurando a Israel o refúgio do Deus eterno.",
    l: ["“Braços eternos” é imagem do apoio permanente de Deus sob o seu povo.",
        "A bênção fala da expulsão dos inimigos cananeus, meta da conquista."] },
  { r: "Deuteronômio 34:10", t: "E nunca mais se levantou em Israel profeta algum como Moisés, a quem o SENHOR conhecera face a face.",
    c: "Epílogo do livro, que louva Moisés como único profeta a quem Deus falou face a face.",
    l: ["“Face a face” indica comunhão íntima e direta, privilégio singular de Moisés.",
        "Moisés morreu em Moabe, antes de Israel entrar em Canaã sob Josué."] },
{ r: "Josué 1:8", t: "Não se aparte da tua boca o livro desta lei; antes medita nele dia e noite, para que tenhas cuidado de fazer conforme a tudo quanto nele está escrito; porque então farás prosperar o teu caminho, e então prudentemente te conduzirás.",
    c: "Deus instrui Josué na transição de liderança após a morte de Moisés, ordenando que a lei mosaica fosse o fundamento do governo de Israel em Canaã.",
    l: ["“O livro desta lei” refere-se ao Pentateuco, os cinco livros escritos por Moisés.",
        "“Meditar dia e noite” indica leitura recitada em voz baixa, prática comum no antigo Israel."] },
  { r: "Josué 1:9", t: "Não to mandei eu? Esforça-te, e tem bom ânimo; não temas, nem te espantes, porque o Senhor teu Deus é contigo por onde quer que andares.",
    c: "Deus fala a Josué logo após a morte de Moisés, quando Josué assume a liderança e precisa atravessar o Jordão para entrar em Canaã.",
    l: ["O Jordão é o rio que separa o deserto a leste da terra de Canaã a oeste; Israel o atravessou em frente a Jericó.",
        "“Esforça-te” traduz um verbo hebraico que significa manter-se firme diante do perigo militar."] },
  { r: "Josué 3:17", t: "Porém os sacerdotes que levavam a arca da aliança do Senhor pararam firmes no meio do Jordão, e todo o Israel passou a pé enxuto, até que todo o povo acabou de passar o Jordão.",
    c: "Narra a travessia milagrosa do rio Jordão sob a liderança de Josué, quando os sacerdotes que carregavam a arca ficaram no leito seco.",
    l: ["O Jordão desce do monte Hermom até o mar Morto, formando um vale profundo; por isso a passagem a seco foi sinal sobrenatural.",
        "A arca da aliança era um baú de madeira de acácia coberto de ouro, símbolo da presença de Deus com Israel."] },
  { r: "Josué 6:20", t: "Gritou, pois, o povo, e os sacerdotes tocaram as buzinas; e sucedeu que, ouvindo o povo o sonido da buzina, gritou o povo com grande brado; e o muro caiu abaixo, e o povo subiu à cidade, cada um em frente de si, e tomaram a cidade.",
    c: "Registra a queda das muralhas de Jericó após sete dias de marcha ao redor da cidade, primeira conquista de Israel em Canaã.",
    l: ["Jericó situa-se no vale do Jordão, a cerca de 10 km a noroeste do mar Morto, num oásis junto à fonte de Eliseu.",
        "As buzinas eram chifres de carneiro, chamados shofar, usados para convocar o povo e para ritos sagrados."] },
  { r: "Josué 10:13", t: "E o sol se deteve, e a lua parou, até que o povo se vingou dos seus inimigos. Não está isto escrito no livro de Jasher? E o sol se deteve no meio do céu, e não se apressou a pôr-se, quase um dia inteiro.",
    c: "Descreve o prolongamento do dia durante a batalha de Gibeão, quando Josué comandou o exército de Israel contra a coalizão dos amorreus.",
    l: ["Gibeão era uma cidade cananeia ao norte de Jerusalém, na região montanhosa de Judá.",
        "O livro de Jasher era uma antiga coleção poética israelita citada também em 2 Samuel, hoje perdida."] },
  { r: "Josué 21:45", t: "Nenhuma promessa falhou de todas as boas palavras que o Senhor falara à casa de Israel; tudo se cumpriu.",
    c: "Conclusão do relato da repartição da terra entre as tribos, encerrando a conquista com a afirmação da fidelidade de Deus.",
    l: ["Canaã é a faixa entre o mar Mediterrâneo e o rio Jordão, dividida entre as tribos por sorteio.",
        "Os levitas não receberam território próprio, mas cidades separadas para habitação."] },
  { r: "Josué 24:15", t: "Porém, se vos parece mal aos vossos olhos servir ao Senhor, escolhei hoje a quem sirvais: se aos deuses a quem serviram vossos pais, que estavam dalém do rio, ou aos deuses dos amorreus, em cuja terra habitais; porém eu e a minha casa serviremos ao Senhor.",
    c: "No final de sua vida, Josué reúne Israel em Siquém e convoca o povo a renovar a aliança com Deus antes de sua morte.",
    l: ["“Dalém do rio” refere-se à região além do Eufrates, de onde Abraão veio para Canaã.",
        "Siquém fica entre os montes Ebal e Gerizim, no centro da terra, local tradicional de alianças."] },
  { r: "Juízes 2:16", t: "Levantou o Senhor juízes, que os livraram da mão dos que os roubavam.",
    c: "Resume o ciclo do livro dos Juízes: após a apostasia de Israel, Deus suscitava libertadores para livrá-lo dos inimigos.",
    l: ["Os juízes não eram apenas magistrados, mas líderes militares e civis levantados em momentos de crise.",
        "O período dos juízes durou cerca de três séculos, entre a morte de Josué e a coroação de Saul."] },
  { r: "Juízes 5:31", t: "Assim pereçam todos os teus inimigos, ó Senhor! Porém os que te amam sejam como o sol quando sai na sua força. E sossegou a terra quarenta anos.",
    c: "É o final do cântico de Débora, composto após a vitória de Israel sobre o exército cananeu de Sísera.",
    l: ["Débora foi profetisa e juíza que julgava Israel debaixo de uma palmeira, entre Ramá e Betel.",
        "Os quarenta anos indicam uma geração de paz, medida frequente na narrativa bíblica."] },
  { r: "Juízes 6:12", t: "Então o anjo do Senhor lhe apareceu, e lhe disse: O Senhor é contigo, homem valoroso.",
    c: "O anjo chama Gideão em Ofra, quando Israel estava oprimido pelos midianitas; Gideão malhava trigo escondido no lagar.",
    l: ["O lagar era um tanque escavado na rocha usado para pisar uvas e extrair o vinho.",
        "Os midianitas eram povos nômades do deserto a leste, que saqueavam as colheitas de Israel."] },
  { r: "Juízes 6:16", t: "E o Senhor lhe disse: Certamente eu serei contigo, e ferirás os midianitas como se fossem um só homem.",
    c: "Deus confirma a Gideão a vitória sobre os midianitas, apesar de ele se considerar o menor da sua casa.",
    l: ["Gideão pertencia à tribo de Manassés e à família de Abiezer.",
        "A expressão “como se fossem um só homem” indica derrota completa e sem resistência."] },
  { r: "Juízes 7:7", t: "Então o Senhor disse a Gideão: Com estes trezentos homens que lamberam a água te salvarei, e entregarei os midianitas na tua mão; e todo o resto do povo vá cada um ao seu lugar.",
    c: "Deus reduz o exército de Gideão de milhares para trezentos, para que a vitória fosse atribuída ao Senhor e não à força humana.",
    l: ["Os trezentos foram escolhidos pela maneira de beber a água, separando os vigilantes dos descuidados.",
        "A batalha ocorreu no vale de Jezreel, planície fértil ao norte de Israel."] },
  { r: "Juízes 16:28", t: "Então Sansão clamou ao Senhor, e disse: Senhor Jeová, lembra-te de mim, peço-te, e fortalece-me somente esta vez, ó Deus, para que de uma só vez me vingue dos filisteus por causa dos meus dois olhos.",
    c: "Preso e cego pelos filisteus, Sansão ora antes de derrubar as colunas do templo de Dagom em Gaza.",
    l: ["Gaza era uma das cinco cidades principais dos filisteus, na planície costeira do sudoeste.",
        "Sansão era nazireu desde o nascimento, consagrado a Deus e proibido de cortar o cabelo."] },
  { r: "Juízes 21:25", t: "Naqueles dias não havia rei em Israel; porém cada um fazia o que parecia reto aos seus olhos.",
    c: "Versículo que encerra o livro dos Juízes, explicando a desordem moral e religiosa daquele período.",
    l: ["A ausência de rei significava falta de autoridade central e de unidade entre as tribos.",
        "A frase marca o contraste com o período monárquico iniciado com Saul e Davi."] },
  { r: "Rute 1:16", t: "Porém Rute disse: Não me instes para que te deixe, e me torne de trás de ti; porque aonde quer que tu fores, irei eu, e onde quer que pousares, ali pousarei eu; o teu povo é o meu povo, o teu Deus é o meu Deus.",
    c: "Rute, viúva moabita, recusa abandonar sua sogra Noemi e abraça o povo e o Deus de Israel.",
    l: ["Moabe ficava a leste do mar Morto, região montanhosa cortada pelo rio Arnom.",
        "“Pousar” refere-se ao descanso noturno no caminho entre Moabe e Belém."] },
  { r: "Rute 1:17", t: "Onde tu morreres, morrerei eu, e ali serei sepultada; assim me faça o Senhor, e outro tanto, se outra coisa que a morte me separar de ti.",
    c: "Rute sela seu compromisso com Noemi por juramento solene, invocando o nome do Senhor.",
    l: ["Sepultar-se no mesmo lugar de um ente querido expressava vínculo familiar permanente no Oriente antigo.",
        "Os juramentos eram confirmados invocando o nome divino, com fórmula de maldição sobre si mesmo."] },
  { r: "Rute 2:12", t: "O Senhor te recompense o teu feito, e seja cumprido o teu galardão pelo Senhor, Deus de Israel, sob cujas asas te vieste abrigar.",
    c: "Boaz abençoa Rute quando ela colhe espigas em seus campos em Belém, demonstrando bondade à estrangeira.",
    l: ["Colher espigas atrás dos ceifeiros era direito dos pobres, estrangeiros, órfãos e viúvas, garantido pela Lei.",
        "A figura das “asas” de Deus remete à proteção oferecida a quem busca refúgio na aliança."] },
  { r: "Rute 4:17", t: "E as vizinhas deram-lhe nome, dizendo: A Noemi nasceu um filho. E chamaram o seu nome Obede; este é o pai de Jessé, pai de Davi.",
    c: "Rute casa-se com Boaz e gera Obede, tornando-se bisavó do rei Davi e antepassada do Messias.",
    l: ["Obede significa “servo”, e sua genealogia liga a linhagem davídica ao período dos juízes.",
        "Belém, também chamada Efrata, situa-se a cerca de 10 km ao sul de Jerusalém."] },
  { r: "1 Samuel 1:27", t: "Por este menino orava eu; e o Senhor atendeu à minha petição, que eu lhe fizera.",
    c: "Ana, estéril por muito tempo, entrega seu filho Samuel para servir no santuário de Siló, cumprindo seu voto.",
    l: ["Siló era o principal centro religioso de Israel antes do templo, onde ficava a arca da aliança.",
        "O voto de Ana previa consagrar o filho a Deus por todos os dias de sua vida."] },
  { r: "1 Samuel 2:2", t: "Não há santo como o Senhor; porque não há outro fora de ti; e rocha nenhuma há como o nosso Deus.",
    c: "Trecho do cântico de Ana, oração de exaltação a Deus após o nascimento de Samuel.",
    l: ["“Rocha” era imagem comum para descrever Deus como firme, protetor e refúgio seguro.",
        "O cântico de Ana influenciou o Magnificat, o cântico de Maria no Evangelho de Lucas."] },
  { r: "1 Samuel 3:10", t: "Então o Senhor veio, e parou, e chamou como das outras vezes: Samuel, Samuel! E Samuel disse: Fala, porque o teu servo ouve.",
    c: "Deus chama Samuel pela primeira vez à noite, no santuário de Siló, sob os cuidados do sacerdote Eli.",
    l: ["A lâmpada do santuário ainda não se apagava indica que faltava pouco para o amanhecer.",
        "O menino Samuel servia ao Senhor vestido de éfode de linho, peça usada pelos sacerdotes."] },
  { r: "1 Samuel 7:12", t: "Então tomou Samuel uma pedra, e a pôs entre Mizpá e Sem, e chamou-lhe Ebenézer; e disse: Até aqui nos ajudou o Senhor.",
    c: "Depois da vitória sobre os filisteus, Samuel ergue um memorial celebrando o socorro de Deus a Israel.",
    l: ["Ebenézer significa “pedra de ajuda” ou “pedra do socorro” em hebraico.",
        "Mizpá situa-se na região de Benjamim, ao norte de Jerusalém, ponto de reunião das tribos."] },
  { r: "1 Samuel 12:24", t: "Tão-somente temei ao Senhor, e servi-o fielmente com todo o vosso coração; porque vede quão grandiosas coisas vos fez.",
    c: "Samuel, já idoso, exorta Israel a permanecer fiel a Deus depois de reconhecer Saul como rei.",
    l: ["A expressão “com todo o vosso coração” indica inteireza e sinceridade na devoção, não apenas ritos externos.",
        "Israel pedira um rei “como todas as nações”, deixando de ter o Senhor como rei direto."] },
  { r: "1 Samuel 15:22", t: "Porém Samuel disse: Tem, porventura, o Senhor tanto agrado em holocaustos e sacrifícios, como em que se obedeça à palavra do Senhor? Eis que o obedecer é melhor do que o sacrificar, e o atender melhor é do que a gordura de carneiros.",
    c: "Samuel repreende Saul após ele poupar o melhor do despojo dos amalequitas, desobedecendo à ordem divina.",
    l: ["O holocausto era o sacrifício totalmente queimado no altar, oferta de consagração a Deus.",
        "A gordura era considerada a parte mais nobre do animal e pertencia ao Senhor no sacrifício."] },
  { r: "1 Samuel 16:7", t: "Porém o Senhor disse a Samuel: Não atentes para a sua aparência, nem para a grandeza da sua estatura, porque eu o rejeitei; porque o Senhor não vê como vê o homem, pois o homem vê o que está diante dos olhos, porém o Senhor olha para o coração.",
    c: "Deus rejeita Eliabe e escolhe Davi, o filho mais moço de Jessé, para ser ungido rei em Belém.",
    l: ["A unção com óleo marcava a escolha divina e a capacitação pelo Espírito em Israel.",
        "A estatura de Saul havia impressionado o povo; Deus mostra que o critério dele é o coração."] },
  { r: "1 Samuel 17:47", t: "E toda esta congregação saberá que o Senhor não salva com espada, nem com lança; porque do Senhor é a guerra, e ele vos entregará em nossas mãos.",
    c: "Davi fala ao gigante filisteu Golias no vale de Elá, confiando em Deus e não em armas de guerra.",
    l: ["O vale de Elá fica a sudoeste de Jerusalém, entre as montanhas de Judá e a planície filisteia.",
        "Golias era de Gate, uma das cinco cidades principais dos filisteus."] },
  { r: "2 Samuel 5:10", t: "E Davi se ia fortalecendo, porque o Senhor Deus dos Exércitos era com ele.",
    c: "Resume o crescimento do reino de Davi depois de conquistar Jerusalém e torná-la capital de todo o Israel.",
    l: ["“Senhor dos Exércitos” traduz Javé Sabaoth, referindo-se a Deus como comandante das hostes celestes.",
        "Jerusalém situa-se no planalto de Judá, entre o mar Mediterrâneo e o mar Morto."] },
  { r: "2 Samuel 6:14", t: "E Davi saltava com todas as suas forças diante do Senhor; e estava Davi cingido de um éfode de linho.",
    c: "Davi conduz a arca da aliança a Jerusalém em meio a danças e celebração, diante de todo o Israel.",
    l: ["O éfode de linho era uma vestimenta curta usada em contextos sagrados, diferente do traje real.",
        "A arca havia ficado cerca de vinte anos em Quiriate-Jearim antes de ser levada à capital."] },
  { r: "2 Samuel 7:22", t: "Por isso tu és grande, ó Senhor Deus; porque não há outro como tu, nem há Deus algum além de ti, segundo tudo o que temos ouvido com os nossos ouvidos.",
    c: "Oração de Davi após a promessa de Deus de estabelecer para sempre a sua dinastia, a aliança davídica.",
    l: ["A promessa de uma casa eterna para Davi fundamenta a esperança messiânica em Israel.",
        "Davi desejava construir um templo, mas Deus reservou essa obra para seu filho Salomão."] },
  { r: "2 Samuel 9:7", t: "E disse-lhe Davi: Não temas, porque decerto usarei contigo de beneficência por amor de Jônatas, teu pai, e te restituirei todas as terras de Saul, teu pai, e tu comerás continuamente à minha mesa.",
    c: "Davi mostra bondade a Mefibosete, filho aleijado de Jônatas, cumprindo a aliança de amizade com o amigo falecido.",
    l: ["“Comer à mesa do rei” era sinal de honra e sustento permanente concedido a alguém do círculo real.",
        "Mefibosete ficara aleijado dos pés desde criança, ao cair quando sua ama o levava fugindo."] },
  { r: "2 Samuel 12:7", t: "Então disse Natã a Davi: Tu és este homem. Assim diz o Senhor Deus de Israel: Eu te ungi rei sobre Israel, e eu te livrei das mãos de Saul.",
    c: "O profeta Natã confronta Davi pelo adultério com Bate-Seba e pela morte de Urias, usando uma parábola.",
    l: ["A parábola do cordeirinho fez Davi se indignar antes de perceber que ele próprio era o culpado.",
        "Natã foi profeta na corte de Davi e de Salomão, e também anunciou a sucessão do trono."] },
  { r: "2 Samuel 22:2", t: "E disse: O Senhor é a minha rocha, e a minha fortaleza, e o meu libertador.",
    c: "Início do cântico de Davi após o Senhor livrá-lo da mão de todos os seus inimigos e de Saul.",
    l: ["Fortalezas eram refúgios naturais nas rochas dos montes, onde se podia resistir a ataques.",
        "Este cântico aparece quase idêntico no Salmo 18."] },
  { r: "2 Samuel 22:31", t: "Quanto a Deus, o seu caminho é perfeito; a palavra do Senhor é provada; ele é escudo para todos os que nele se refugiam.",
    c: "Davi exalta a integridade dos caminhos de Deus em meio às perseguições que sofreu.",
    l: ["O escudo era arma defensiva dos soldados israelitas, geralmente de madeira revestida de couro ou metal.",
        "A imagem de Deus como escudo aparece com frequência nos Salmos de Davi."] },
  { r: "2 Samuel 24:14", t: "Então disse Davi a Gade: Estou em grande angústia; porém caiamos nas mãos do Senhor, porque muitas são as suas misericórdias; mas nas mãos dos homens não caia eu.",
    c: "Davi escolhe o castigo divino após o censo pecaminoso de Israel, preferindo a misericórdia de Deus à crueldade humana.",
    l: ["O censo era condenado quando feito por orgulho militar, pois contava o povo como força própria.",
        "Gade era o profeta que acompanhava Davi e transmitia as palavras do Senhor."] },
  { r: "1 Reis 2:3", t: "E guarda a ordenança do Senhor teu Deus, para andares nos seus caminhos, e para guardares os seus estatutos, e os seus mandamentos, e os seus juízos, e os seus testemunhos, como está escrito na lei de Moisés, para que prosperes em tudo quanto fizeres, e para onde quer que te voltares.",
    c: "Davi, à beira da morte, orienta Salomão a obedecer à lei de Moisés para que seu reino seja firmado.",
    l: ["A lei mosaica compreendia mandamentos, estatutos e juízos que regiam a vida religiosa e civil de Israel.",
        "O trono de Davi ficava em Jerusalém, capital escolhida por ele para unir as tribos."] },
  { r: "1 Reis 3:9", t: "A teu servo, pois, dá um coração entendido para julgar a teu povo, para que prudentemente discirna entre o bem e o mal; porque quem poderia julgar a este teu tão grande povo?",
    c: "Salomão pede sabedoria a Deus em Gibeão, em vez de riquezas ou longa vida, logo após assumir o trono.",
    l: ["Gibeão era o grande lugar alto onde ficava o tabernáculo antes da construção do templo.",
        "O “coração entendido” no hebraico evoca um coração que escuta, capaz de discernir."] },
  { r: "1 Reis 8:23", t: "E disse: Senhor Deus de Israel, não há Deus como tu, em cima nos céus nem embaixo na terra, que guardas a aliança e a misericórdia para com os teus servos que andam de todo o seu coração diante de ti.",
    c: "Início da oração de Salomão na dedicação do templo em Jerusalém, diante de todo o povo de Israel.",
    l: ["O templo foi construído no monte Moriá, em Jerusalém, levando sete anos para ser concluído.",
        "A aliança incluía promessas de bênção pela obediência e de juízo pela desobediência."] },
  { r: "1 Reis 10:9", t: "Bendito seja o Senhor teu Deus, que se agradou de ti para te colocar no trono de Israel; porque o Senhor tem amado a Israel para sempre, por isso te estabeleceu como rei, para fazeres juízo e justiça.",
    c: "A rainha de Sabá louva o Deus de Salomão após visitá-lo em Jerusalém e conhecer sua sabedoria.",
    l: ["Sabá ficava no extremo sul da Arábia, região rica em especiarias, ouro e incenso.",
        "A viagem entre Sabá e Jerusalém atravessava cerca de 2 mil quilômetros de deserto."] },
  { r: "1 Reis 17:6", t: "E os corvos lhe traziam pão e carne pela manhã, como também pão e carne à noite; e bebia do ribeiro.",
    c: "Deus sustenta o profeta Elias junto ao ribeiro de Querite, durante a seca anunciada sobre Israel.",
    l: ["O ribeiro de Querite ficava a leste do Jordão, onde Elias se escondeu do rei Acabe.",
        "Os corvos são aves impuras pela lei mosaica, mas aqui servem de instrumento divino."] },
  { r: "1 Reis 18:21", t: "Então Elias se chegou a todo o povo, e disse: Até quando coxeareis entre dois pensamentos? Se o Senhor é Deus, segui-o; e se Baal, segui-o. Porém o povo nada lhe respondeu.",
    c: "No monte Carmelo, Elias desafia o povo de Israel a escolher entre o Senhor e Baal, deus dos cananeus.",
    l: ["O monte Carmelo ergue-se junto ao mar Mediterrâneo, no noroeste de Israel.",
        "Baal era o deus cananeu da chuva e da fertilidade, cultuado com sacrifícios e profetas próprios."] },
  { r: "1 Reis 19:12", t: "E depois do terremoto um fogo; porém também o Senhor não estava no fogo; e depois do fogo uma voz mansa e delicada.",
    c: "Elias encontra Deus no monte Horebe, também chamado Sinai, após fugir da ameaça de Jezabel.",
    l: ["Horebe é o nome usado para o Sinai, a montanha onde Moisés recebeu a lei.",
        "A “voz mansa e delicada” contrasta com fenômenos grandiosos, revelando o modo suave do falar divino."] },
  { r: "1 Reis 22:14", t: "Porém Micaías disse: Vive o Senhor, que o que o Senhor me disser, isso falarei.",
    c: "Micaías responde ao rei Acabe, afirmando que só dirá a verdade recebida do Senhor, contra os falsos profetas.",
    l: ["“Vive o Senhor” era fórmula de juramento solene no antigo Israel.",
        "Acabe reinou sobre Israel no norte, ao lado de Jezabel, promovendo o culto a Baal."] },
  { r: "2 Reis 2:11", t: "E sucedeu que, indo eles caminhando e falando, eis que um carro de fogo, com cavalos de fogo, os separou um do outro; e Elias subiu ao céu num redemoinho.",
    c: "Descreve a ascensão de Elias ao céu, testemunhada por Eliseu, que recebe sua sucessão profética.",
    l: ["O manto de Elias caiu para Eliseu, símbolo da transmissão do ofício profético.",
        "O Jordão havia sido dividido por Elias antes, ao golpear as águas com seu manto."] },
  { r: "2 Reis 5:14", t: "Então desceu, e mergulhou no Jordão sete vezes, conforme a palavra do homem de Deus; e a sua carne tornou-se como a carne de um menino, e ficou purificado.",
    c: "Naamã, comandante sírio, é curado da lepra ao obedecer à ordem do profeta Eliseu de banhar-se no Jordão.",
    l: ["Naamã era general do exército da Síria, cuja capital era Damasco, ao norte de Israel.",
        "O número sete na Bíblia simboliza totalidade e perfeição, não apenas quantidade."] },
  { r: "2 Reis 6:16", t: "E ele disse: Não temas; porque mais são os que estão conosco do que os que estão com eles.",
    c: "Eliseu tranquiliza seu servo cercado pelo exército sírio em Dotã, revelando a proteção celestial de Israel.",
    l: ["Dotã ficava ao norte de Samaria, na rota entre a Síria e a região montanhosa de Efraim.",
        "Eliseu sucedeu Elias no ministério profético no reino do norte, Israel."] },
  { r: "2 Reis 6:17", t: "E orou Eliseu, e disse: Senhor, peço-te, abre os olhos deste moço, para que veja. Então o Senhor abriu os olhos do moço, e ele viu; e eis que o monte estava cheio de cavalos e carros de fogo em redor de Eliseu.",
    c: "Deus abre os olhos do servo de Eliseu para que ele veja o exército celestial que os protegia dos sírios.",
    l: ["“Carros de fogo” descrevem uma visão espiritual, não equipamento militar literal.",
        "Nessa época a Síria pressionava Israel e tentava capturar Eliseu."] },
  { r: "2 Reis 18:5", t: "No Senhor Deus de Israel confiou, de maneira que depois dele não houve quem lhe fosse semelhante entre todos os reis de Judá, nem entre os que foram antes dele.",
    c: "Elogio ao rei Ezequias, que removeu os lugares altos e confiou em Deus diante do avanço assírio.",
    l: ["Ezequias foi rei de Judá quando Senaqueribe, da Assíria, sitiou Jerusalém.",
        "Os “lugares altos” eram santuários em colinas, frequentemente usados para cultos idólatras."] },
  { r: "2 Reis 20:5", t: "Volta, e dize a Ezequias, capitão do meu povo: Assim diz o Senhor, o Deus de Davi teu pai: Ouvi a tua oração, e vi as tuas lágrimas; eis que eu te sararei; ao terceiro dia subirás à casa do Senhor.",
    c: "Deus cura Ezequias de uma enfermidade mortal pela intercessão do profeta Isaías, concedendo-lhe mais quinze anos.",
    l: ["O profeta Isaías atuou em Jerusalém nos reinados de Uzias, Jotão, Acaz e Ezequias.",
        "“Ao terceiro dia” indicava o tempo previsto para a recuperação e o retorno ao templo."] },
  { r: "2 Reis 23:25", t: "E antes dele não houve rei semelhante, que se convertesse ao Senhor com todo o seu coração, e com toda a sua alma, e com todas as suas forças, conforme toda a lei de Moisés; e depois dele nunca se levantou outro tal.",
    c: "Avaliação do reinado de Josias, que promoveu grande reforma religiosa ao encontrar o livro da lei no templo.",
    l: ["Josias subiu ao trono com oito anos e reinou trinta e um anos em Jerusalém.",
        "A reforma removeu ídolos e destruiu altares pagãos em Judá e até em Betel."] },
  { r: "1 Crônicas 4:10", t: "E invocou Jabez ao Deus de Israel, dizendo: Se me abençoares muitíssimo, e meus termos ampliares, e a tua mão for comigo, e fizeres que do mal não seja aflito! E Deus lhe concedeu o que lhe tinha pedido.",
    c: "Registro de Jabez nas genealogias de Judá, exemplo de oração atendida em meio às listas genealógicas.",
    l: ["Os capítulos iniciais de Crônicas traçam genealogias desde Adão até o retorno do exílio.",
        "“Ampliar os termos” significa estender as fronteiras do território."] },
  { r: "1 Crônicas 16:11", t: "Buscai ao Senhor e a sua força; buscai a sua face continuamente.",
    c: "Faz parte do salmo entoado por Davi quando a arca da aliança foi levada a Jerusalém.",
    l: ["“Buscar a face” indica procurar a presença e o favor de Deus em oração.",
        "A arca foi colocada numa tenda que Davi preparou na cidade de Davi."] },
  { r: "1 Crônicas 17:16", t: "Então entrou o rei Davi, e ficou perante o Senhor, e disse: Quem sou eu, Senhor Deus, e qual é a minha casa, que me trouxeste até aqui?",
    c: "Davi expressa humildade diante da promessa de que sua dinastia seria eterna, respondendo à revelação do profeta Natã.",
    l: ["“Minha casa” refere-se à família e à linhagem de Davi, não a um edifício.",
        "A promessa registrada aqui corresponde à aliança davídica de 2 Samuel 7."] },
  { r: "1 Crônicas 21:13", t: "Então disse Davi a Gade: Estou em grande angústia; caia eu, pois, nas mãos do Senhor, porque são muitíssimas as suas misericórdias; mas nas mãos dos homens não caia eu.",
    c: "Crônicas reproduz a escolha de Davi após o censo pecaminoso, preferindo a disciplina de Deus à vingança humana.",
    l: ["O censo contava os homens de guerra de Israel, expressando confiança na força militar.",
        "A praga que se seguiu atingiu Israel até que Davi edificou um altar."] },
  { r: "1 Crônicas 28:20", t: "E disse Davi a Salomão seu filho: Esforça-te e tem bom ânimo, e faze a obra; não temas, nem te desmaies, porque o Senhor Deus, meu Deus, há de ser contigo; não te deixará, nem te desamparará, até que acabes toda a obra do serviço da casa do Senhor.",
    c: "Davi encarrega Salomão de construir o templo, animando-o com a certeza da presença de Deus.",
    l: ["Davi reuniu materiais e recursos para o templo, embora não pudesse edificá-lo por ter derramado muito sangue.",
        "O templo seria a casa de Deus em Jerusalém, centro do culto de Israel."] },
  { r: "1 Crônicas 29:11", t: "Tua, ó Senhor, é a grandeza, e o poder, e a glória, e a vitória, e a majestade; porque teu é tudo quanto há nos céus e na terra; teu, ó Senhor, é o reino, e tu te exaltaste por chefe sobre todos.",
    c: "Davi louva a Deus diante da assembleia, reconhecendo que tudo provém do Senhor, na oferta para o templo.",
    l: ["Este louvor integra a oração de Davi na consagração dos donativos para a construção do templo.",
        "A linguagem de reino e majestade influenciou a doxologia do Pai Nosso."] },
  { r: "2 Crônicas 1:10", t: "Dá-me, pois, agora sabedoria e conhecimento, para que possa sair e entrar perante este povo; porque quem poderia julgar a este teu tão grande povo?",
    c: "Salomão pede sabedoria a Deus em Gibeão, e Crônicas destaca esse pedido como início de seu reinado.",
    l: ["“Sair e entrar” é expressão hebraica para conduzir e liderar o povo.",
        "Gibeão distava cerca de 10 km ao noroeste de Jerusalém."] },
  { r: "2 Crônicas 7:14", t: "E se o meu povo, que se chama pelo meu nome, se humilhar, e orar, e buscar a minha face, e se converter dos seus maus caminhos, então eu ouvirei dos céus, e perdoarei os seus pecados, e sararei a sua terra.",
    c: "Resposta de Deus a Salomão após a dedicação do templo, prometendo perdão e restauração ao povo arrependido.",
    l: ["A promessa foi dada em sonho a Salomão depois da consagração do templo.",
        "“Chamar-se pelo meu nome” indica que Israel pertencia ao Senhor."] },
  { r: "2 Crônicas 15:2", t: "E saiu ao encontro de Asa, e disse-lhe: Ouvi-me, Asa, e todo o Judá e Benjamim: O Senhor está convosco, enquanto vós estais com ele; e se o buscardes, achá-lo-eis; mas se o deixardes, ele vos deixará.",
    c: "O profeta Azarias exorta o rei Asa e o povo a buscar o Senhor, após a vitória sobre os etíopes.",
    l: ["Asa reinou em Judá e promoveu reforma religiosa, removendo altares estranhos.",
        "Benjamim era a tribo vizinha de Judá ao norte, aliada na reforma."] },
  { r: "2 Crônicas 16:9", t: "Porque, quanto ao Senhor, seus olhos passam por toda a terra, para mostrar-se forte para com aqueles cujo coração é perfeito para com ele; nisto procedeste loucamente, pois desde agora haverá guerras contra ti.",
    c: "O profeta Hanani repreende Asa por confiar no rei da Síria em vez de confiar em Deus contra Baasa.",
    l: ["Asa havia contratado Ben-Hadade, rei da Síria, para atacar o reino do norte.",
        "A frase “coração perfeito” indica lealdade integral a Deus."] },
  { r: "2 Crônicas 20:15", t: "E disse: Dai ouvidos, todo o Judá, e vós, moradores de Jerusalém, e tu, ó rei Josafá; assim o Senhor vos diz: Não temais, nem vos assusteis por causa desta grande multidão, porque a peleja não é vossa, mas de Deus.",
    c: "O profeta Jaaziel tranquiliza Josafá e o povo diante da invasão das nações aliadas de Moabe, Amom e Edom.",
    l: ["Josafá foi rei de Judá e incentivou o ensino da lei ao povo.",
        "Os inimigos vinham de além do mar Salgado, isto é, do mar Morto."] },
  { r: "2 Crônicas 20:17", t: "Nesta peleja não tereis que pelejar; parai, estai em pé, e vede a salvação do Senhor para convosco, ó Judá e Jerusalém. Não temais, nem vos assusteis; amanhã saí-lhes ao encontro, porque o Senhor é convosco.",
    c: "Deus instrui Judá a permanecer firme e ver a sua vitória, no episódio da invasão confederada contra Josafá.",
    l: ["A estratégia incomum foi louvar a Deus à frente do exército, sem combater.",
        "O vale onde se reuniram recebeu depois o nome de vale de Beraca, que significa “bênção”."] },
  { r: "Esdras 1:2", t: "Assim diz Ciro, rei da Pérsia: O Senhor Deus dos céus me deu todos os reinos da terra, e me encarregou de lhe edificar uma casa em Jerusalém, que está em Judá.",
    c: "Decreto de Ciro permitindo o retorno dos judeus do exílio babilônico para reconstruir o templo.",
    l: ["Ciro foi rei da Pérsia e conquistou a Babilônia em 539 a.C., liberando os judeus.",
        "O exílio babilônico durou cerca de setenta anos, conforme anunciado pelos profetas."] },
  { r: "Esdras 3:11", t: "E cantavam a uma voz, louvando e dando graças ao Senhor, dizendo: Porque é bom, porque a sua misericórdia dura para sempre sobre Israel. E todo o povo jubilou com grande júbilo, louvando ao Senhor, por se ter lançado o fundamento da casa do Senhor.",
    c: "Os retornados lançam os fundamentos do segundo templo, e o povo celebra com cânticos de louvor.",
    l: ["“A sua misericórdia dura para sempre” é refrão do Salmo 136.",
        "O segundo templo foi edificado no mesmo local do templo de Salomão, em Jerusalém."] },
  { r: "Esdras 7:10", t: "Porque Esdras tinha preparado o seu coração para buscar a lei do Senhor e para a cumprir, e para ensinar em Israel os seus estatutos e os seus juízos.",
    c: "Apresenta Esdras, sacerdote e escriba, que liderou a reforma religiosa após o retorno do exílio.",
    l: ["Esdras era escriba versado na lei de Moisés e servia na Pérsia diante do rei Artaxerxes.",
        "“Preparar o coração” indica disposição deliberada e constante, não impulso momentâneo."] },
  { r: "Esdras 8:22", t: "Porque me envergonhei de pedir ao rei um exército e cavaleiros para nos defenderem do inimigo no caminho, porquanto tínhamos falado ao rei, dizendo: A mão do nosso Deus é sobre todos aqueles que o buscam, para o bem; mas o seu poder e a sua ira contra todos aqueles que o abandonam.",
    c: "Esdras recusa escolta militar por confiar na proteção de Deus na viagem da Babilônia a Jerusalém.",
    l: ["A viagem entre a Babilônia e Jerusalém atravessava cerca de mil quilômetros de deserto.",
        "“A mão de Deus” é expressão que indica a ação e o cuidado divinos."] },
  { r: "Neemias 1:4", t: "E sucedeu que, ouvindo eu estas palavras, assentei-me, e chorei, e lamentei por alguns dias; e estive jejuando e orando perante o Deus dos céus.",
    c: "Neemias, copeiro do rei persa, chora ao saber que Jerusalém continua em ruínas e com seus muros derrubados.",
    l: ["Neemias servia na corte de Artaxerxes, em Susã, capital de inverno do império persa.",
        "Jejuar e orar era prática comum de luto e súplica no antigo Israel."] },
  { r: "Neemias 2:20", t: "E respondi-lhes, e disse: O Deus dos céus é o que nos fará prosperar, e nós, seus servos, nos levantaremos e edificaremos; mas vós não tendes parte, nem direito, nem memorial em Jerusalém.",
    c: "Neemias responde a Sambalate e Tobias, que zombavam da reconstrução dos muros de Jerusalém.",
    l: ["Sambalate era governador de Samaria e Tobias, líder amonita, ambos opositores de Neemias.",
        "“Memorial” refere-se ao direito de ser lembrado na cidade, inclusive no culto."] },
  { r: "Neemias 4:14", t: "Olhei, e levantei-me, e disse aos nobres, aos magistrados e ao resto do povo: Não temais; lembrai-vos do Senhor, grande e terrível, e pelejai por vossos irmãos, vossos filhos, vossas filhas, vossas mulheres e vossas casas.",
    c: "Diante da ameaça de ataque, Neemias anima o povo a confiar em Deus e a defender suas famílias enquanto trabalham nos muros.",
    l: ["Os construtores trabalhavam com uma mão na obra e outra segurando a arma, tamanha a ameaça.",
        "Os muros de Jerusalém foram reconstruídos em apenas cinquenta e dois dias."] },
  { r: "Neemias 8:10", t: "E disse-lhes: Ide, e comei as gorduras, e bebei as doçuras, e enviai porções aos que não têm nada preparado para si; porque este dia é consagrado ao nosso Senhor; portanto, não vos entristeçais; porque a alegria do Senhor é a vossa força.",
    c: "Neemias e Esdras animam o povo, que chorava ao ouvir a leitura da lei, a celebrar com alegria e partilha.",
    l: ["“Gorduras” e “doçuras” indicam os melhores alimentos e bebidas doces da festa.",
        "A leitura pública da lei ocorreu na praça diante da porta das Águas, em Jerusalém."] },
  { r: "Ester 2:17", t: "E o rei amou a Ester mais do que a todas as mulheres, e ela alcançou graça e benevolência diante dele, mais do que todas as virgens; e pôs a coroa real na sua cabeça, e a fez rainha em lugar de Vasti.",
    c: "Ester, judia criada por seu primo Mardoqueu, é escolhida rainha pelo rei Assuero, na Pérsia.",
    l: ["Assuero é o nome hebraico do rei persa Xerxes I, que reinou de 486 a 465 a.C.",
        "A capital do império era Susã, onde ficava o palácio real."] },
  { r: "Ester 4:14", t: "Porque, se de todo te calares neste tempo, socorro e livramento de outra parte virá para os judeus, mas tu e a casa de teu pai perecereis; e quem sabe se para tal tempo como este chegaste a este reino?",
    c: "Mardoqueu exorta Ester a interceder junto ao rei contra o decreto de extermínio planejado por Hamã.",
    l: ["Hamã era ministro do rei e tramou destruir os judeus por ódio a Mardoqueu.",
        "A providência divina, embora não nomeada no livro, é tema central de Ester."] },
  { r: "Ester 4:16", t: "Vai, ajunta todos os judeus que se acharem em Susã, e jejuai por mim, e não comais nem bebais por três dias, nem de dia nem de noite; e eu e as minhas servas também jejuaremos; e assim irei ter com o rei, ainda que seja contra a lei; e se perecer, pereci.",
    c: "Ester decide arriscar a vida apresentando-se ao rei sem ser chamada, pedindo jejum de todo o povo judeu.",
    l: ["Aproximar-se do rei sem convite podia ser punido com morte, salvo se ele estendesse o cetro de ouro.",
        "O jejum de três dias era sinal de súplica intensa e humilhação diante de Deus."] },
  { r: "Ester 9:22", t: "Como os dias em que os judeus tiveram sossego dos seus inimigos, e o mês que se lhes mudou de tristeza em alegria, e de luto em dias de festa; para que os fizessem dias de banquetes e de alegria, e de mandarem porções uns aos outros e dádivas aos pobres.",
    c: "Institui a festa de Purim, celebrando a libertação dos judeus do plano de Hamã na Pérsia.",
    l: ["Purim vem da palavra “sorte”, pois Hamã lançou sortes para escolher o dia do extermínio.",
        "A festa é celebrada no mês de Adar, que corresponde a fevereiro e março."] },
{ r: "Jó 1:21", t: "E disse: Nu saí do ventre de minha mãe e nu tornarei para lá; o Senhor o deu, e o Senhor o tomou; bendito seja o nome do Senhor.",
    c: "Jó era um homem íntegro e temente a Deus que vivia na terra de Uz. Após perder bens e filhos numa série de desgraças, ele pronunciou esta frase de submissão e adoração.",
    l: ["“Ventre de minha mãe” expressa a fragilidade e o desamparo do ser humano ao nascer, sem posses nem roupas.",
        "Uz, terra de Jó, ficava na região de Edom, a leste de Israel e de Canaã, próxima ao deserto da Arábia."] },
  { r: "Jó 5:17", t: "Eis que bem-aventurado é o homem a quem Deus castiga; não desprezes, pois, a correção do Todo-Poderoso.",
    c: "Elifaz, o temanita, foi um dos três amigos que vieram consolar Jó. Nesta fala, ele apresenta a correção de Deus como disciplina que traz felicidade a quem a aceita.",
    l: ["“Todo-Poderoso” traduz o hebraico Shaddai, título divino frequente no livro de Jó.",
        "Temã era uma cidade edomita conhecida por seus sábios, situada a sudeste de Israel."] },
  { r: "Jó 13:15", t: "Ainda que ele me mate, nele esperarei; contudo os meus caminhos defenderei diante dele.",
    c: "Jó responde aos seus amigos num discurso em que reafirma sua integridade. Mesmo sem entender seu sofrimento, ele decide manter a confiança em Deus.",
    l: ["“Esperar” aqui tem o sentido hebraico de aguardar confiante, e não apenas desejar.",
        "“Diante dele” refere-se a apresentar a causa judicial, na imagem de um tribunal diante de Deus."] },
  { r: "Jó 14:1", t: "O homem, nascido da mulher, é de bem poucos dias e cheio de inquietação.",
    c: "Em seu lamento, Jó reflete sobre a brevidade e a inquietação da vida humana, depois de comparar a vida a um serviço militar e a um jornaleiro à espera do pagamento.",
    l: ["“Bem poucos dias” indica a curta duração da vida em contraste com a eternidade de Deus.",
        "A imagem do “jornaleiro” era comum numa economia agrícola em que se pagava o trabalhador por dia."] },
  { r: "Jó 19:25", t: "Porque eu sei que o meu Redentor vive, e que por fim se levantará sobre a terra.",
    c: "Esta é uma das declarações mais célebres do livro: Jó, já rejeitado pelos amigos, apela para um Redentor que vivesse e o defendesse.",
    l: ["“Redentor” traduz o hebraico goel, o parente que resgatava o parente pobre ou vingava o sangue.",
        "“Sobre a terra” aponta para a expectativa de um testemunho ou vindicação terrena após sua morte."] },
  { r: "Jó 23:10", t: "Mas ele sabe o meu caminho; prove-me, e sairei como o ouro.",
    c: "Jó argumenta que Deus conhece seu caminho e que seria aprovado mesmo numa provação. Ele desejava apresentar seu caso diretamente a Deus.",
    l: ["O ouro era refinado no fogo para se separarem as impurezas dos metais preciosos.",
        "O “ouro” era metal de grande valor no antigo Oriente Próximo, medido por peso em siclos."] },
  { r: "Jó 28:28", t: "E disse ao homem: Eis que o temor do Senhor é a sabedoria, e apartar-se do mal é a inteligência.",
    c: "No capítulo 28, Jó descreve a busca humana pela sabedoria. Depois de mostrar que os tesouros se extraem da terra, conclui que o temor do Senhor é a verdadeira sabedoria.",
    l: ["O capítulo menciona a prata, o ouro e o ferro extraídos das minas e medidos por peso.",
        "O “siclo” era a unidade de peso padrão, cerca de onze gramas, usada nas transações."] },
  { r: "Jó 33:4", t: "O Espírito de Deus me fez; e a inspiração do Todo-Poderoso me deu vida.",
    c: "Eliú, o mais jovem dos interlocutores, fala a Jó. Ele afirma que a vida do homem vem do Espírito de Deus e prepara o terreno para a resposta divina.",
    l: ["“Espírito de Deus” traduz o hebraico ruach, que significa sopro, vento ou espírito.",
        "Eliú era de Buz, região ligada aos descendentes de Abraão e situada a leste de Israel."] },
  { r: "Jó 36:26", t: "Eis que Deus é grande, e nós não o compreendemos, e o número dos seus anos não se pode esquadrinhar.",
    c: "Ainda Eliú exalta a grandeza de Deus, dizendo que os anos do Senhor são incompreensíveis e não podem ser contados como os dos homens.",
    l: ["“Número dos seus anos” contrasta com a brevidade da vida humana, contada por dias e anos de colheitas.",
        "A idade dos homens no antigo Israel era contada pelas estações e pelas safras agrícolas."] },
  { r: "Jó 38:4", t: "Onde estavas tu, quando eu fundava a terra? Faze-mo saber, se tens inteligência.",
    c: "Deus responde a Jó do meio de um redemoinho, com perguntas que mostram os limites do entendimento humano diante da criação.",
    l: ["“Fundava a terra” usa a imagem de edificar um edifício com alicerce.",
        "A “terra” aqui é o mundo habitado, concebido como alicerce firme sobre os mares."] },
  { r: "Jó 40:4", t: "Eis que sou vil; que te responderia eu? A minha mão porei sobre a minha boca.",
    c: "Diante das perguntas de Deus, Jó reconhece sua pequenez e decide calar-se, cobrindo a boca como sinal de humildade.",
    l: ["Cobrir a boca era gesto de silêncio e respeito diante de alguém superior, comum no antigo Oriente.",
        "“Vil” traduz o hebraico qalal, no sentido de ser pequeno ou desprezível diante de Deus."] },
  { r: "Jó 42:2", t: "Bem sei eu que tudo podes, e nenhum dos teus pensamentos pode ser impedido.",
    c: "Jó responde a Deus reconhecendo seu poder absoluto e que nenhum propósito divino pode ser impedido. É o começo de sua submissão final.",
    l: ["“Nenhum dos teus pensamentos” reflete a ideia de que os planos de Deus não podem ser frustrados.",
        "“Tudo podes” traduz a soberania do Criador sobre toda a criação."] },
  { r: "Jó 42:5", t: "Com os ouvidos dos homens ouvira falar de ti; mas agora te vêem os meus olhos.",
    c: "Jó compara o que ouvira de Deus por tradição com o encontro direto que agora tem, depois que o Senhor lhe falou do redemoinho.",
    l: ["“Ouvidos dos homens” indica conhecimento indireto, transmitido de geração em geração.",
        "“Olhos” representa a experiência pessoal direta, contraste frequente no hebraico entre ouvir e ver."] },
  { r: "Jó 42:10", t: "E o Senhor virou o cativeiro de Jó, quando orava pelos seus amigos; e o Senhor acrescentou a Jó outro tanto em dobro a tudo quanto dantes possuía.",
    c: "Após Jó orar pelos seus amigos, Deus restaura sua sorte e lhe devolve em dobro o que havia perdido, encerrando o livro com um final de restauração.",
    l: ["“Virou o cativeiro” é expressão hebraica para restaurar a sorte ou mudar a condição de alguém.",
        "A restauração “em dobro” refletia o costume de devolver bens com acréscimo a quem sofrera perda injusta."] },
  { r: "Jó 42:12", t: "Assim abençoou o Senhor o último estado de Jó mais do que o primeiro; porque teve catorze mil ovelhas, e seis mil camelos, e mil juntas de bois, e mil jumentas.",
    c: "O epílogo do livro descreve a bênção final de Deus sobre Jó, maior do que a anterior. Ele morreu velho e farto de dias.",
    l: ["“Juntas de bois” era a unidade de tração, o par de animais usado no arado.",
        "Camelos, ovelhas, bois e jumentas eram a base da riqueza pastoral e agrícola no antigo Oriente."] },
  { r: "Salmos 1:1", t: "Bem-aventurado o varão que não anda segundo o conselho dos ímpios, nem se detém no caminho dos pecadores, nem se assenta na roda dos escarnecedores.",
    c: "O Salmo 1 abre o livro como um prólogo que contrasta o justo e o ímpio. Não traz título nem autor indicado, servindo de introdução a toda a coleção.",
    l: ["“Andar, deter-se, assentar” descrevem uma progressão de envolvimento crescente com o pecado.",
        "“Roda dos escarnecedores” era o círculo de homens que zombavam e desprezavam a lei de Deus."] },
  { r: "Salmos 1:2", t: "Antes tem o seu prazer na lei do Senhor, e na sua lei medita de dia e de noite.",
    c: "Ainda no salmo introdutório, o justo se define pelo prazer na lei do Senhor. A meditação substitui o conselho dos ímpios do verso anterior.",
    l: ["“Lei” traduz o hebraico torah, que significa instrução ou ensino, não apenas mandamentos.",
        "“De dia e de noite” é expressão semítica para tempo integral e contínuo."] },
  { r: "Salmos 16:11", t: "Far-me-ás ver a vereda da vida; na tua presença há fartura de alegrias; à tua mão direita há delícias perpetuamente.",
    c: "Salmo de Davi, chamado de Mictão, em que ele expressa confiança em Deus como sua porção e refúgio, contrastando com a sorte dos idólatras.",
    l: ["“Vereda da vida” é o caminho que conduz à vida na presença de Deus.",
        "“À tua mão direita” indicava lugar de honra e proximidade junto ao soberano."] },
  { r: "Salmos 19:1", t: "Os céus declaram a glória de Deus e o firmamento anuncia a obra das suas mãos.",
    c: "Salmo de Davi que celebra a revelação de Deus na criação e, em seguida, na sua lei. A primeira parte fala da glória divina nos céus.",
    l: ["“Firmamento” traduz o hebraico raqia, a abóbada do céu vista como expansão sobre a terra.",
        "“Céus” no antigo Israel designava o espaço visível acima da terra, morada das estrelas."] },
  { r: "Salmos 23:1", t: "O Senhor é o meu pastor; nada me faltará.",
    c: "Salmo de Davi, que foi pastor de ovelhas antes de ser rei; ele usa a figura do pastor para descrever o cuidado de Deus.",
    l: ["Na região de Judá as ovelhas dependem do pastor para encontrar pasto e água em terreno seco e rochoso.",
        "“Pastor” era também título dado a reis no antigo Oriente Próximo; Davi aplica o título a Deus."] },
  { r: "Salmos 23:4", t: "Ainda que eu andasse pelo vale da sombra da morte, não temeria mal algum, porque tu estás comigo; a tua vara e o teu cajado me consolam.",
    c: "No mesmo salmo, Davi descreve a confiança do rebanho nos vales escuros. A vara e o cajado são os instrumentos do pastor.",
    l: ["“Vale da sombra da morte” pode designar desfiladeiros fundos e sombrios perto do mar Morto.",
        "A “vara” servia para contar e defender as ovelhas; o “cajado”, para guiá-las e corrigi-las."] },
  { r: "Salmos 27:1", t: "O Senhor é a minha luz e a minha salvação; a quem temerei? O Senhor é a força da minha vida; de quem me recearei?",
    c: "Salmo de Davi que expressa confiança em Deus diante de inimigos. A linguagem militar combina luz, salvação e fortaleza.",
    l: ["“Luz” simboliza vida, orientação e segurança, em contraste com a escuridão do perigo.",
        "“Força da minha vida” é a defesa que garante a sobrevivência do salmista."] },
  { r: "Salmos 34:8", t: "Provai e vede que o Senhor é bom; bem-aventurado o homem que nele confia.",
    c: "Salmo de Davi, segundo o título composto quando ele se fingiu de louco diante de Abimeleque. O convite é à experiência pessoal da bondade divina.",
    l: ["“Provai” usa a imagem de experimentar o sabor dos alimentos.",
        "“Confia” traduz o hebraico chasah, buscar refúgio, como quem se abriga sob uma rocha."] },
  { r: "Salmos 37:4", t: "Deleita-te também no Senhor, e ele te concederá o que deseja o teu coração.",
    c: "Salmo sapiencial de Davi que anima os justos diante da prosperidade dos ímpios, exortando à paciência e à confiança no Senhor.",
    l: ["“Deleita-te” expressa encontrar prazer e satisfação em Deus.",
        "“O que deseja o teu coração” aponta para anseios que Deus mesmo alinha à sua vontade."] },
  { r: "Salmos 46:1", t: "Deus é o nosso refúgio e fortaleza, socorro bem presente na angústia.",
    c: "Salmo dos filhos de Corá, canto de confiança em meio a catástrofes. Serviu de inspiração ao hino “Castelo Forte”, de Lutero.",
    l: ["“Refúgio” é o lugar seguro onde alguém se abriga do perigo.",
        "“Fortaleza” designa uma praça militar fortificada, com muros e torres de defesa."] },
  { r: "Salmos 51:10", t: "Cria em mim, ó Deus, um coração puro, e renova em mim um espírito reto.",
    c: "Salmo de Davi, composto segundo o título após o seu pecado com Bate-Seba. É uma oração de arrependimento e renovação interior.",
    l: ["“Coração” no hebraico é a sede da vontade e do pensamento, não apenas das emoções.",
        "“Renova” sugere recriar, pedindo um novo começo interior."] },
  { r: "Salmos 90:12", t: "Ensina-nos a contar os nossos dias, de tal maneira que alcancemos corações sábios.",
    c: "Salmo atribuído a Moisés, o único salmo com esse título. Ele contrasta a eternidade de Deus com a brevidade e fragilidade da vida humana.",
    l: ["“Contar os dias” usa a imagem de numerar os dias um a um.",
        "A vida humana é comparada à erva, que de manhã floresce e à tarde seca."] },
  { r: "Salmos 91:1", t: "Aquele que habita no esconderijo do Altíssimo, à sombra do Onipotente descansará.",
    c: "Salmo anônimo de confiança e proteção, muito citado em momentos de perigo. Contrasta a segurança do justo com o juízo sobre os ímpios.",
    l: ["“Esconderijo” e “sombra” evocam abrigo contra o calor do sol no deserto.",
        "“Altíssimo” (Elyon) e “Onipotente” (Shaddai) são títulos de Deus que enfatizam sua exaltação e poder."] },
  { r: "Salmos 100:4", t: "Entrai pelas portas dele com gratidão, e em seus átrios com louvor; louvai-o e bendizei o seu nome.",
    c: "Salmo de ação de graças, talvez usado nas procissões de entrada no templo. Convida a multidão a entrar com gratidão e louvor.",
    l: ["“Portas” e “átrios” referem-se ao recinto do templo em Jerusalém, com pátios para os adoradores.",
        "“Bendizei o seu nome” significa reconhecer em público quem Deus é."] },
  { r: "Salmos 103:1", t: "Bendize, ó minha alma, ao Senhor, e tudo o que há em mim bendiga o seu santo nome.",
    c: "Salmo de Davi que começa com um convite da alma a bendizer a Deus por seus benefícios: perdão, cura e renovo.",
    l: ["“Alma” traduz o hebraico nephesh, o ser vivo inteiro, não apenas a parte imaterial.",
        "“Santo nome” representa o caráter e a reputação de Deus revelados ao povo."] },
  { r: "Salmos 119:105", t: "Lâmpada para os meus pés é tua palavra, e luz para o meu caminho.",
    c: "Salmo acróstico, o mais longo do livro, formado por estrofes que seguem o alfabeto hebraico. Todo ele celebra a palavra de Deus.",
    l: ["A lâmpada de barro com azeite era pequena e iluminava apenas o caminho imediato.",
        "A “palavra” aqui é a torah, a instrução divina aplicada aos passos diários do fiel."] },
  { r: "Salmos 121:1", t: "Elevo os meus olhos para os montes: de onde me vem o socorro?",
    c: "Cântico dos degraus, cantado por peregrinos que subiam a Jerusalém. O salmista volta o olhar para as montanhas ao redor da cidade.",
    l: ["Jerusalém fica em região montanhosa; as montanhas podiam lembrar perigos ou os santuários pagãos.",
        "“Socorro” traduz o hebraico ezer, auxílio que vem de quem pode livrar."] },
  { r: "Salmos 126:3", t: "Grandes coisas fez o Senhor por nós, por isso estamos alegres.",
    c: "Cântico dos degraus que recorda o retorno do exílio babilônico e o fim do cativeiro. O povo celebra as grandes obras de Deus.",
    l: ["“Sião” é outro nome de Jerusalém, a colina onde se erguia o templo.",
        "O retorno do exílio foi autorizado pelo decreto de Ciro, rei da Pérsia, em 538 a.C."] },
  { r: "Salmos 139:14", t: "Eu te louvarei, porque de um modo assombroso e tão maravilhoso fui feito; maravilhosas são as tuas obras, e a minha alma o sabe muito bem.",
    c: "Salmo de Davi sobre o conhecimento que Deus tem do ser humano. O salmista admira a formação do corpo humano pelas mãos de Deus.",
    l: ["“Fui feito” remete ao ato de tecer ou moldar, como o artesão no tear.",
        "“De um modo assombroso” traduz o hebraico que une temor e admiração diante da criação."] },
  { r: "Salmos 150:6", t: "Todo o ser vivente louve ao Senhor. Louvai ao Senhor.",
    c: "Último salmo do livro, que encerra a coleção com um convite universal ao louvor. O salmo lista vários instrumentos musicais.",
    l: ["“Ser vivente” traduz o hebraico nefesh, todo ser que respira.",
        "Este salmo final fecha o livro com a expressão que em hebraico é Aleluia, “louvai ao Senhor”."] },
  { r: "Provérbios 1:7", t: "O temor do Senhor é o princípio da ciência; os loucos desprezam a sabedoria e a instrução.",
    c: "Abertura do livro de Provérbios, atribuído a Salomão. O temor do Senhor é apresentado como fundamento de todo conhecimento verdadeiro.",
    l: ["“Temor do Senhor” não é medo servil, mas reverência e submissão a Deus.",
        "“Ciência” traduz o hebraico da’at, conhecimento obtido por experiência e ensino."] },
  { r: "Provérbios 3:5", t: "Confia no Senhor de todo o teu coração, e não te estribes no teu próprio entendimento.",
    c: "Instrução de um pai a seu filho, na seção de Provérbios 3. Exorta a confiar em Deus em vez de depender da própria razão.",
    l: ["“Coração” é, no hebraico, a sede da vontade e da decisão.",
        "“Estribes” significa apoiar-se, como quem se firma num bastão para não cair."] },
  { r: "Provérbios 3:6", t: "Reconhece-o em todos os teus caminhos, e ele endireitará as tuas veredas.",
    c: "Continuação do conselho paterno: reconhecer a Deus em todos os caminhos garante direção segura para a vida.",
    l: ["“Caminhos” e “veredas” são metáforas para as escolhas e a conduta diária.",
        "“Endireitará” significa tornar plano e reto o caminho, imagem das estradas preparadas para viajar."] },
  { r: "Provérbios 4:23", t: "Sobre tudo o que se deve guardar, guarda o teu coração, porque dele procede a vida.",
    c: "Aviso de um pai ao filho sobre a importância do coração. No contexto, fala-se de guardar a vida interior de influências corrompidas.",
    l: ["“Guarda” usa a imagem do vigia que protege uma entrada.",
        "“Coração” no hebraico é o centro da vontade, do pensamento e da vida moral."] },
  { r: "Provérbios 10:12", t: "O ódio excita contendas, mas o amor cobre todas as transgressões.",
    c: "Começo da coleção de provérbios curtos de Salomão. O contraste entre ódio e amor é apresentado por seus efeitos nas relações humanas.",
    l: ["“Contendas” indica brigas e conflitos que se espalham.",
        "“Cobre” traduz o hebraico que indica encobrir ou perdoar a ofensa, não escondê-la por hipocrisia."] },
  { r: "Provérbios 12:15", t: "O caminho do tolo é reto aos seus olhos, mas o que dá ouvidos ao conselho é sábio.",
    c: "Provérbio sapiencial que contrasta o tolo e o sábio. O tolo confia em si mesmo, enquanto o sábio busca conselho externo.",
    l: ["“Reto aos seus olhos” indica a autojustificação de quem julga seu próprio caminho.",
        "“Conselho” refere-se à orientação de pessoas experientes, prática valorizada no antigo Israel."] },
  { r: "Provérbios 15:1", t: "A resposta branda desvia o furor, mas a palavra dura suscita a ira.",
    c: "Provérbio sobre o poder das palavras. Uma resposta calma evita conflitos, enquanto a palavra áspera os acende.",
    l: ["“Branda” traduz o hebraico que indica suavidade e mansidão no falar.",
        "“Furor” e “ira” descrevem a reação violenta de quem se sente ofendido."] },
  { r: "Provérbios 16:3", t: "Entrega ao Senhor as tuas obras, e teus pensamentos serão estabelecidos.",
    c: "Provérbio que ensina a entregar os planos a Deus. Faz parte da seção de instruções de Salomão sobre a vida prática e a soberania divina.",
    l: ["“Entrega” usa a imagem de rolar o peso sobre outra pessoa, transferindo a carga.",
        "“Estabelecidos” significa firmados, confirmados, no sentido de planos que se firmam."] },
  { r: "Provérbios 17:17", t: "Em todo o tempo ama o amigo, e na angústia nasce o irmão.",
    c: "Provérbio sobre a verdadeira amizade, que se prova na adversidade. O amigo leal se torna como irmão nos momentos difíceis.",
    l: ["“Angústia” indica aperto, adversidade ou calamidade.",
        "A solidariedade de irmão era essencial num mundo sem seguridade social ou amparo estatal."] },
  { r: "Provérbios 18:10", t: "O nome do Senhor é uma torre forte; o justo corre para ela e está seguro.",
    c: "Provérbio que compara o nome do Senhor a uma fortaleza. O justo corre para ela em busca de proteção.",
    l: ["“Torre forte” era refúgio elevado dentro de uma cidade cercada de muros.",
        "“Seguro” traduz a ideia de estar posto em lugar alto e protegido do inimigo."] },
  { r: "Provérbios 19:20", t: "Ouve o conselho e recebe a correção, para que sejas sábio nos teus últimos dias.",
    c: "Provérbio que exorta a ouvir conselho e aceitar correção. O objetivo é tornar-se sábio para os dias que virão.",
    l: ["“Correção” traduz o hebraico musar, disciplina e instrução formativa.",
        "“Últimos dias” aponta para a velhice e o fim da vida, quando se colhem os frutos das escolhas."] },
  { r: "Provérbios 22:6", t: "Instrui o menino no caminho em que deve andar, e até quando envelhecer não se desviará dele.",
    c: "Provérbio sobre a educação dos filhos, muito citado. Ensinar desde cedo molda o caráter que permanece na vida adulta.",
    l: ["“Instrui” traduz o hebraico chanak, dedicar ou iniciar, termo ligado à inauguração.",
        "“Menino” designa a criança ou jovem em fase de formação; o ensino começava em casa."] },
  { r: "Provérbios 25:11", t: "Como maçãs de ouro em salvas de prata, assim é a palavra dita a seu tempo.",
    c: "Coleção de provérbios de Salomão copiada pelos homens de Ezequias. Compara a palavra oportuna a joias valiosas.",
    l: ["“Salvas de prata” eram bandejas ou esculturas de prata em que se encaixavam frutas.",
        "“Maçãs de ouro” indica provavelmente frutos de ouro em relevo, objeto de grande valor artístico."] },
  { r: "Provérbios 27:17", t: "Ferro com ferro se afia; assim o homem afia o rosto do seu amigo.",
    c: "Provérbio que ilustra o efeito do convívio entre amigos. O atrito mútuo afia o caráter, como a pedra afia o ferro.",
    l: ["“Afia” refere-se ao processo de amolar o fio de ferramentas de ferro.",
        "“Rosto” representa a disposição e a expressão da pessoa, ou seja, o próprio caráter."] },
  { r: "Provérbios 31:30", t: "Enganosa é a graça, e vaidade a formosura, mas a mulher que teme ao Senhor, essa será louvada.",
    c: "Encerramento do poema acróstico sobre a mulher virtuosa. O valor verdadeiro não está na aparência, mas no temor do Senhor.",
    l: ["“Graça” indica beleza e encanto exterior que enganam.",
        "“Vaidade” traduz o hebraico hevel, algo passageiro e frágil como vapor."] },
  { r: "Eclesiastes 1:2", t: "Vaidade de vaidades, diz o Pregador, vaidade de vaidades! Tudo é vaidade.",
    c: "Abertura do livro, tradicionalmente atribuído a Salomão, o “Pregador”. Ele avalia a vida “debaixo do sol” e a considera passageira.",
    l: ["“Vaidade” traduz o hebraico hevel, que significa vapor, sopro ou algo fugaz.",
        "“Pregador” traduz o hebraico Qohelet, aquele que convoca ou fala à assembleia."] },
  { r: "Eclesiastes 3:1", t: "Tudo tem o seu tempo determinado, e há tempo para todo o propósito debaixo do céu.",
    c: "Passagem célebre sobre os tempos da vida. O Pregador observa que tudo na criação tem um propósito determinado por Deus.",
    l: ["“Debaixo do céu” é expressão usada para designar a esfera da vida terrestre.",
        "“Tempo determinado” aponta para o tempo fixado, não para o acaso."] },
  { r: "Eclesiastes 3:11", t: "Tudo fez formoso em seu tempo; também pôs o mundo no coração do homem, sem que este possa descobrir a obra que Deus fez desde o princípio até ao fim.",
    c: "No mesmo capítulo dos tempos, o Pregador afirma que Deus fez tudo formoso e pôs em nós o senso de eternidade, sem que possamos compreender plenamente sua obra.",
    l: ["“Formoso em seu tempo” indica a beleza de cada propósito no seu devido momento.",
        "“Pôs o mundo no coração” refere-se ao anseio de eternidade, que excede a vida presente."] },
  { r: "Eclesiastes 4:6", t: "Melhor é um punhado com quietude do que ambas as mãos cheias com trabalho e aflição de espírito.",
    c: "Provérbio dentro do ensaio de Eclesiastes sobre o trabalho e a ganância. Prefere-se pouco com paz a muito com fadiga.",
    l: ["“Punhado” era medida de mão, o que cabe na palma fechada.",
        "“Ambas as mãos cheias” indica grande quantidade obtida à custa de esforço e aflição."] },
  { r: "Eclesiastes 4:9", t: "Melhor é serem dois do que um, porque têm melhor paga do seu trabalho.",
    c: "Observação da seção sobre a solidão e o companheirismo. O Pregador declara superior a sorte de dois que trabalham juntos.",
    l: ["“Melhor paga” indica o produto do trabalho repartido entre os dois.",
        "Na economia antiga o trabalho em parceria era comum na agricultura e no ofício manual."] },
  { r: "Eclesiastes 5:10", t: "Quem ama o dinheiro jamais se fartará de dinheiro; e quem ama a abundância nunca se fartará dos seus frutos; também isto é vaidade.",
    c: "Reflexão sobre a inutilidade da riqueza. O desejo de dinheiro nunca se satisfaz, pois sempre busca mais.",
    l: ["“Fartará” indica saciar a fome; no caso do dinheiro, a satisfação nunca chega.",
        "A riqueza do antigo Israel se media em ovelhas, grãos, prata e terras."] },
  { r: "Eclesiastes 7:1", t: "Melhor é a boa fama do que o melhor unguento, e o dia da morte do que o dia do nascimento de alguém.",
    c: "Série de provérbios sobre a sabedoria. O Pregador contrasta a fama duradoura com o perfume temporário e pondera o sentido da morte.",
    l: ["“Unguento” era óleo aromático extraído de ervas, usado para perfumar e embalsamar.",
        "O incenso e os unguentos vinham de especiarias importadas de regiões distantes e custavam caro."] },
  { r: "Eclesiastes 7:14", t: "No dia da prosperidade goza do bem, mas no dia da adversidade considera; porque também Deus fez a este em oposição àquele, para que o homem nada descubra do que há de vir depois dele.",
    c: "No mesmo capítulo, o Pregador ensina a receber tanto a prosperidade quanto a adversidade como vindas de Deus.",
    l: ["“Dia da adversidade” contrapõe-se ao dia da prosperidade, formando pares de tempos.",
        "A expressão “do que há de vir depois dele” indica que o homem não controla o futuro."] },
  { r: "Eclesiastes 9:10", t: "Tudo quanto te vier à mão para fazer, faze-o conforme as tuas forças, porque na sepultura, para onde tu vais, não há obra, nem indústria, nem sabedoria alguma.",
    c: "Exortação ao trabalho diligente enquanto há vida. O Pregador lembra que na sepultura cessa toda atividade terrena.",
    l: ["“Sepultura” traduz o hebraico sheol, o mundo dos mortos na concepção hebraica.",
        "“Indústria” aqui significa ocupação ou atividade planejada, e não o setor econômico moderno."] },
  { r: "Eclesiastes 11:1", t: "Lança o teu pão sobre as águas, porque depois de muitos dias o acharás.",
    c: "Conselho sobre a generosidade e a iniciativa. Lançar o pão sobre as águas é imagem de semear sem garantia imediata de retorno.",
    l: ["O versículo evoca o comércio marítimo, em que mercadorias eram enviadas por navio e retornavam dias depois.",
        "“Pão” representa o sustento e os recursos empenhados em investimento ou bondade."] },
  { r: "Eclesiastes 12:1", t: "Lembra-te do teu Criador nos dias da tua mocidade, antes que venham os maus dias, e cheguem os anos dos quais venhas a dizer: Não tenho neles contentamento.",
    c: "Início do epílogo poético do livro. O Pregador exorta a lembrar do Criador enquanto a juventude permite servir a Deus.",
    l: ["“Dias da mocidade” indica a fase de vigor, contraposta aos “maus dias” da velhice.",
        "A velhice é descrita nos versos seguintes com imagens de decadência física."] },
  { r: "Eclesiastes 12:13", t: "De tudo o que se tem ouvido, o fim é: Teme a Deus, e guarda os seus mandamentos; porque este é o dever de todo o homem.",
    c: "Conclusão do livro. Depois de examinar tudo, o Pregador resume o dever humano em temer a Deus e guardar seus mandamentos.",
    l: ["“Teme a Deus” retoma o lema do livro de Provérbios, que faz do temor do Senhor o princípio da sabedoria.",
        "“Dever de todo o homem” traduz o hebraico que indica obrigação e limite de toda pessoa."] },
  { r: "Cantares 1:2", t: "Beije-me ele com os beijos da sua boca; porque melhor é o teu amor do que o vinho.",
    c: "Abertura do Cântico dos Cânticos, atribuído a Salomão. É um poema de amor entre o amado e a sulamita, celebrando o amor conjugal.",
    l: ["“Vinho” era bebida comum nas festas e símbolo de alegria e comunhão.",
        "O beijo era sinal de afeto próprio do contexto da promessa de casamento entre os noivos."] },
  { r: "Cantares 1:5", t: "Eu sou morena, mas formosa, ó filhas de Jerusalém, como as tendas de Quedar, como as cortinas de Salomão.",
    c: "A sulamita fala às filhas de Jerusalém, explicando sua pele escurecida pelo trabalho ao sol nas vinhas.",
    l: ["“Quedar” designava tribos árabes nômades do deserto, cujas tendas eram feitas de pelo de cabra preto.",
        "“Cortinas de Salomão” eram os tapetes ou toldos ricamente bordados de sua tenda real."] },
  { r: "Cantares 2:1", t: "Eu sou a rosa de Sarom, o lírio dos vales.",
    c: "A amada se descreve com duas flores humildes, contrastando com a riqueza das descrições das belezas ao seu redor.",
    l: ["“Sarom” é a planície costeira fértil de Israel, entre o monte Carmelo e Jope.",
        "O lírio dos vales era flor silvestre comum, símbolo de beleza simples e delicada."] },
  { r: "Cantares 2:11", t: "Porque eis que passou o inverno; a chuva cessou, e se foi.",
    c: "Chegada a primavera, o amado convida a amada a sair. O fim do inverno marca o tempo de cantar e florescer.",
    l: ["Na terra de Israel, o inverno é a estação chuvosa, de dezembro a março.",
        "A “chuva” que cessa é a chuva tardia, que fecha o ciclo agrícola antes da primavera."] },
  { r: "Cantares 2:15", t: "Apanhai-nos as raposas, as raposinhas, que fazem mal às vinhas, porque as nossas vinhas estão em flor.",
    c: "A amada pede ajuda para afastar as raposas que ameaçam as vinhas em flor, imagem dos que perturbam o amor.",
    l: ["As “raposas” (ou chacais) danificavam as videiras novas, comendo brotos e cachos.",
        "“Vinhas em flor” indica a primavera, quando a floração precede a frutificação."] },
  { r: "Cantares 3:11", t: "Saí, ó filhas de Sião, e contemplai ao rei Salomão com a coroa com que o coroou sua mãe no dia do seu desposório e no dia do júbilo do seu coração.",
    c: "Convite às filhas de Sião para ver Salomão em sua coroa nupcial. O trecho celebra o dia do casamento real.",
    l: ["“Sião” é a colina de Jerusalém onde ficava a cidade de Davi e o templo.",
        "“Coroa” era o adorno usado pelo noivo no dia do desposório, talvez um diadema ou grinalda."] },
  { r: "Cantares 4:7", t: "Tu és toda formosa, meu amor, e em ti não há mancha.",
    c: "O amado declara a amada perfeita e sem defeito. A linguagem nupcial descreve a beleza da amada em termos poéticos.",
    l: ["“Mancha” indicava defeito físico ou ritual, aquilo que tornava impuro.",
        "“Meu amor” traduz o hebraico ra’yah, termo de afeto usado repetidamente no poema."] },
  { r: "Cantares 4:15", t: "És a fonte dos jardins, poço das águas vivas, que correm do Líbano.",
    c: "Na descrição do jardim da amada, ele é comparado a fonte e a águas correntes que descem do Líbano.",
    l: ["O “Líbano” é a cadeia montanhosa ao norte de Israel, famosa por seus cedros e neves.",
        "“Águas vivas” são águas de nascente, em movimento, opostas às águas paradas de cisterna."] },
  { r: "Cantares 6:3", t: "Eu sou do meu amado, e o meu amado é meu; ele apascenta o seu rebanho entre os lírios.",
    c: "A amada declara a pertença mútua entre ela e o amado. A imagem pastoral fala do amado apascentando entre os lírios.",
    l: ["O “rebanho” indica ovelhas e cabras, riqueza comum no campo de Israel.",
        "Os “lírios” são flores silvestres que cresciam nos campos e vales na primavera."] },
  { r: "Cantares 8:6", t: "Põe-me como selo sobre o teu coração, como selo sobre o teu braço; porque o amor é forte como a morte; o ciúme é cruel como a sepultura; as suas brasas são brasas de fogo, labaredas do Senhor.",
    c: "Clímax do poema, em que a amada pede ser selada no coração do amado. O amor é descrito como força invencível, forte como a morte.",
    l: ["“Selo” era sinete gravado em pedra, usado para marcar propriedade ou autenticar documentos.",
        "“Sepultura” traduz o hebraico sheol, o mundo dos mortos, aqui imagem de força insaciável."] },
  { r: "Cantares 8:7", t: "As muitas águas não poderiam apagar o amor, nem os rios afogá-lo; ainda que alguém desse todos os bens da sua casa pelo amor, seria de todo desprezado.",
    c: "Conclusão sobre a natureza do amor verdadeiro, que não se compra nem se apaga. Nem as muitas águas podem extinguir o amor.",
    l: ["“Muitas águas” evocam rios caudalosos e enchentes que arrastam tudo.",
        "“Todos os bens da sua casa” representa a maior riqueza que alguém poderia oferecer em troca."] },
{ r: "Isaías 1:18", t: "Vinde, pois, e arrazoemos, diz o Senhor; ainda que os vossos pecados sejam como a escarlata, eles se tornarão brancos como a neve; ainda que sejam vermelhos como o carmesim, se tornarão como a branca lã.",
    c: "Isaías profetizou em Jerusalém no século VIII a.C., chamando Judá ao arrependimento diante de seus pecados e da ameaça assíria.",
    l: ["A escarlata e o carmesim eram corantes vermelhos caros, extraídos de um inseto, símbolos de mancha profunda e difícil de remover.",
        "A neve é rara em Jerusalém, mas comum no monte Hermom, ao norte, de onde descem as águas do Jordão."] },
  { r: "Isaías 6:8", t: "Depois ouvi a voz do Senhor, que dizia: A quem enviarei, e quem há de ir por nós? Então disse eu: Eis-me aqui, envia-me a mim.",
    c: "Relato do chamado de Isaías, ocorrido no ano da morte do rei Uzias, por volta de 740 a.C., no templo de Jerusalém.",
    l: ["O templo visto por Isaías era o de Salomão, em Jerusalém, centro do culto de Israel.",
        "Uzias reinou em Judá por cinquenta e dois anos; sua morte marcou uma mudança política no reino do Sul."] },
  { r: "Isaías 7:14", t: "Portanto o mesmo Senhor vos dará um sinal: eis que a virgem conceberá, e dará à luz um filho, e será o seu nome Emanuel.",
    c: "Isaías fala ao rei Acaz, de Judá, quando este temia a coalizão de Rezim, da Síria, e Peca, de Israel, contra Jerusalém.",
    l: ["Emanuel é nome hebraico composto de duas palavras, que significa Deus conosco.",
        "A coalizão siro-efraimita ameaçava Jerusalém por volta de 735 a.C., tentando forçar Judá a aliar-se contra a Assíria."] },
  { r: "Isaías 9:6", t: "Porque um menino nos nasceu, um filho se nos deu; e o principado está sobre os seus ombros; e o seu nome será: Maravilhoso, Conselheiro, Deus Forte, Pai da Eternidade, Príncipe da Paz.",
    c: "Anúncio messiânico feito ao reino de Judá, que vivia sob a sombra ameaçadora do império assírio.",
    l: ["O principado sobre os ombros refere-se à insígnia que o governante levava nos ombros, símbolo de autoridade real.",
        "Os nomes dados ao menino são títulos de governo, comuns nas coroações dos reis do antigo Oriente."] },
  { r: "Isaías 26:3", t: "Tu conservarás em paz aquele cuja mente está firme em ti; porque ele confia em ti.",
    c: "Cântico de confiança de Judá, que aguardava a intervenção de Deus contra seus opressores.",
    l: ["A mente firme traduz no hebraico a ideia de alguém apoiado e sustentado, imagem de quem repousa em segurança.",
        "Este capítulo é chamado pelos estudiosos de pequeno apocalipse de Isaías, por falar da vitória final de Deus."] },
  { r: "Isaías 40:31", t: "Mas os que esperam no Senhor renovarão as suas forças, subirão com asas como águias; correrão, e não se cansarão; caminharão, e não se fatigarão.",
    c: "Isaías consola o povo de Judá, ameaçado e depois exilado pela Babilônia, afirmando que Deus sustenta quem nele confia.",
    l: ["A águia é ave comum nas montanhas de Judá e sinal de força e visão ao longe.",
        "O exílio na Babilônia ficava a cerca de 1.600 km de Jerusalém, uma viagem de meses a pé."] },
  { r: "Isaías 41:10", t: "Não temas, porque eu sou contigo; não te assombres, porque eu sou teu Deus; eu te fortaleço, e te ajudo, e te sustento com a destra da minha justiça.",
    c: "Deus fala a Israel como seu servo, encorajando-o em meio ao temor das nações poderosas ao seu redor.",
    l: ["A destra, isto é, a mão direita, era o lugar de honra e de força; apoiar-se nela significava proteção e favor.",
        "O trecho faz parte da seção de consolação de Isaías, dirigida aos que seriam levados ao cativeiro."] },
  { r: "Isaías 43:2", t: "Quando passares pelas águas estarei contigo, e quando pelos rios, eles não te submergirão; quando passares pelo fogo, não te queimarás, nem a chama arderá em ti.",
    c: "Isaías assegura a Israel, prestes a passar pela provação do exílio, a presença protetora de Deus.",
    l: ["Passar pelas águas e pelo fogo eram imagens comuns no antigo Oriente para perigos extremos e provações.",
        "Recorda a travessia do mar Vermelho e do rio Jordão, feitos que marcaram a história de Israel."] },
  { r: "Isaías 53:5", t: "Mas ele foi ferido por causa das nossas transgressões, e moído por causa das nossas iniquidades; o castigo que nos traz a paz estava sobre ele, e pelas suas feridas fomos sarados.",
    c: "Quarto cântico do Servo do Senhor, que descreve o sofrimento do Servo em favor do povo de Israel.",
    l: ["Ferido e moído traduzem termos hebraicos que descrevem ferimentos graves de combate e a moagem do grão.",
        "O Servo sofre vicariamente, isto é, em lugar do povo, tema central deste cântico."] },
  { r: "Isaías 55:11", t: "Assim será a minha palavra, que sair da minha boca; ela não voltará para mim vazia, antes fará o que me apraz, e prosperará naquilo para que a enviei.",
    c: "Convite de Deus ao arrependimento, garantindo ao povo de Israel que sua palavra sempre se cumpre.",
    l: ["Palavra, no hebraico dabar, não é só discurso, mas ação e acontecimento que se realiza.",
        "A imagem da chuva que rega a terra, no versículo anterior, ilustra a eficácia da palavra de Deus."] },
  { r: "Isaías 61:1", t: "O Espírito do Senhor Deus está sobre mim; porque o Senhor me ungiu, para pregar boas novas aos mansos; enviou-me a restaurar os contritos de coração, a proclamar liberdade aos cativos, e a abertura de prisão aos presos.",
    c: "Isaías anuncia a missão do Servo ungido, que traz boas novas aos oprimidos e libertação aos cativos.",
    l: ["Ungir com óleo era rito de consagração de reis e sacerdotes; o ungido recebia autoridade para sua missão.",
        "Os cativos e presos retratam tanto a condição social dos oprimidos quanto a situação dos exilados."] },
  { r: "Jeremias 1:5", t: "Antes que eu te formasse no ventre te conheci, e antes que saísses da madre te santifiquei; às nações te dei por profeta.",
    c: "Relato do chamado de Jeremias, filho do sacerdote Hilquias, em Anatote, no décimo terceiro ano do rei Josias, por volta de 627 a.C.",
    l: ["Anatote era uma cidade sacerdotal a cerca de 5 km ao nordeste de Jerusalém, terra natal de Jeremias.",
        "Jeremias era ainda jovem quando recebeu o chamado e exerceu o ministério por cerca de quarenta anos."] },
  { r: "Jeremias 9:23", t: "Assim diz o Senhor: Não se glorie o sábio na sua sabedoria, nem se glorie o forte na sua força; não se glorie o rico nas suas riquezas.",
    c: "Jeremias adverte Judá, já sob ameaça da Babilônia, contra a vanglória dos poderosos e sábios.",
    l: ["Sabedoria, força e riqueza eram os três grandes valores do antigo Oriente, aqui relativizados diante de Deus.",
        "O profeta exortava o povo a gloriar-se em conhecer o Senhor, e não nos bens passageiros."] },
  { r: "Jeremias 17:7", t: "Bendito o homem que confia no Senhor, e cuja confiança é o Senhor.",
    c: "Jeremias contrasta a confiança em Deus com a confiança no homem, dirigindo-se a Judá antes do exílio.",
    l: ["A imagem da árvore plantada junto às águas, no versículo seguinte, retrata quem confia no Senhor.",
        "Confiar, no hebraico, indica apoiar-se e repousar em alguém, como quem se firma numa rocha."] },
  { r: "Jeremias 29:11", t: "Porque eu bem sei os pensamentos que tenho a vosso respeito, diz o Senhor; pensamentos de paz, e não de mal, para vos dar o fim que esperais.",
    c: "Carta de Jeremias aos judeus deportados para a Babilônia, exortando-os a viver e a esperar ali.",
    l: ["O exílio babilônico começou em 597 a.C.; Jeremias escreveu aos cativos para desfazer falsas expectativas de retorno imediato.",
        "A promessa de setenta anos de cativeiro aparece no mesmo capítulo, como prazo do juízo e da restauração."] },
  { r: "Jeremias 29:13", t: "E buscar-me-eis, e me achareis, quando me buscardes de todo o vosso coração.",
    c: "Ainda na carta aos exilados na Babilônia, Jeremias promete que Deus se deixará achar pelos que o buscarem.",
    l: ["Buscar de todo o coração indica entrega total, expressão comum na aliança entre Deus e Israel.",
        "No antigo Israel, buscar a Deus incluía a oração e o retorno sincero à sua lei."] },
  { r: "Jeremias 31:3", t: "Com amor eterno te amei; por isso com benignidade te atraí.",
    c: "Oráculo de consolação ao povo de Israel, prometendo restauração após o juízo do exílio.",
    l: ["O amor eterno traduz o hebraico hesed, a lealdade fiel de Deus à sua aliança.",
        "O capítulo anuncia a futura volta dos cativos e a reconstrução das cidades de Israel."] },
  { r: "Jeremias 31:33", t: "Mas este é o concerto que farei com a casa de Israel depois daqueles dias, diz o Senhor: porei a minha lei no seu interior, e a escreverei no seu coração; e eu serei o seu Deus e eles serão o meu povo.",
    c: "Promessa da nova aliança, anunciada por Jeremias em meio ao anúncio do exílio e da restauração.",
    l: ["Antes a lei estava escrita em tábuas de pedra; agora Deus a escreveria no coração, interiorizando a aliança.",
        "A fórmula eu serei o seu Deus e eles serão o meu povo resume a aliança desde os tempos do êxodo."] },
  { r: "Jeremias 32:17", t: "Ah! Senhor Deus! Eis que tu fizeste os céus e a terra com o teu grande poder, e com o teu braço estendido; não te é impossível nada.",
    c: "Jeremias ora a Deus ao comprar um campo em Anatote, como sinal de que haveria restauração para Judá.",
    l: ["A compra do campo por dezessete siclos de prata aparece no versículo nono deste capítulo.",
        "O siclo era uma unidade de peso e de valor em prata usada em Israel."] },
  { r: "Jeremias 33:3", t: "Clama a mim, e responder-te-ei, e anunciar-te-ei coisas grandes e firmes que não sabes.",
    c: "Palavra de Deus a Jeremias, preso no pátio da guarda, reafirmando a futura restauração de Jerusalém.",
    l: ["Jeremias estava detido no pátio da guarda do palácio real em Jerusalém quando recebeu este oráculo.",
        "Coisas grandes e firmes, no hebraico, designam verdades seguras e inacessíveis ao saber humano."] },
  { r: "Lamentações 3:22-23", t: "As misericórdias do Senhor são a causa de não sermos consumidos, porque as suas misericórdias não têm fim; novas são cada manhã; grande é a tua fidelidade.",
    c: "Lamento do profeta após a destruição de Jerusalém pelos babilônios em 586 a.C., mesclando dor e esperança.",
    l: ["O livro é formado por cinco poemas fúnebres; os capítulos 1, 2 e 4 são acrósticos alfabéticos em hebraico.",
        "Jerusalém foi destruída por Nabucodonosor em 586 a.C., fato que deu origem a estes lamentos."] },
  { r: "Lamentações 3:25", t: "Bom é o Senhor para os que esperam por ele, e para a alma que o busca.",
    c: "O profeta exorta o povo à esperança em Deus mesmo no dia da calamidade nacional.",
    l: ["Esperar, no hebraico qavah, tem a ideia de aguardar com tensão, como cordas esticadas.",
        "Ainda hoje os judeus leem Lamentações no jejum que relembra a queda de Jerusalém."] },
  { r: "Lamentações 3:26", t: "Bom é ter esperança, e aguardar em silêncio a salvação do Senhor.",
    c: "Continuação do chamado à esperança serena em meio ao juízo que caiu sobre Judá.",
    l: ["O silêncio aqui é atitude de submissão confiante diante de Deus, e não ausência de fé.",
        "O versículo faz parte do centro do livro, onde a esperança ressurge no meio do lamento."] },
  { r: "Lamentações 5:21", t: "Converte-nos, ó Senhor, a ti, e nos converteremos; renova os nossos dias como dantes.",
    c: "Oração final do livro, pedindo a restauração de Judá depois da destruição de Jerusalém.",
    l: ["Jerusalém ficou desolada e o templo foi queimado, e o povo orava por dias como os de antes.",
        "Converter, no hebraico shub, significa voltar-se, dar meia-volta em direção a Deus."] },
  { r: "Ezequiel 11:19", t: "E lhes darei um só coração, e porei dentro de vós um novo espírito; e tirarei de sua carne o coração de pedra, e lhes darei um coração de carne.",
    c: "Ezequiel, sacerdote levado cativo à Babilônia em 597 a.C., profetiza aos exilados junto ao rio Quebar.",
    l: ["Tel-Abibe, onde viviam os exilados, situava-se junto ao rio Quebar, canal da Babilônia.",
        "Coração de pedra e coração de carne contrastam dureza e sensibilidade, imagem de renovação interior."] },
  { r: "Ezequiel 18:23", t: "Desejaria eu, de qualquer maneira, a morte do ímpio? diz o Senhor Deus; não desejo antes que se converta dos seus caminhos, e viva?",
    c: "Ezequiel corrige o provérbio dos exilados de que os filhos pagavam pelos pecados dos pais.",
    l: ["O profeta insiste na responsabilidade pessoal: cada um responde por seu próprio caminho.",
        "Converter, no hebraico shub, é voltar-se e mudar de direção, termo central do chamado profético."] },
  { r: "Ezequiel 33:11", t: "Dize-lhes: Vivo eu, diz o Senhor Deus, não tenho prazer na morte do ímpio, mas em que o ímpio se converta do seu caminho, e viva; convertei-vos, convertei-vos dos vossos maus caminhos; pois, por que razão morrereis, ó casa de Israel?",
    c: "Deus designa Ezequiel como atalaia para advertir Israel a se arrepender e viver, já no cativeiro babilônico.",
    l: ["O atalaia era o vigia das muralhas que alertava a cidade sobre o perigo iminente.",
        "Ezequiel foi chamado a advertir tanto os exilados quanto os que ficaram em Judá."] },
  { r: "Ezequiel 36:25", t: "Então aspergirei água pura sobre vós, e ficareis purificados; de todas as vossas imundícies, e de todos os vossos ídolos, vos purificarei.",
    c: "Promessa de purificação e restauração de Israel depois do exílio babilônico.",
    l: ["Aspergir água pura recordava os ritos de purificação do templo e do sacerdócio levítico.",
        "Os ídolos eram imagens de divindades estrangeiras, como as da Babilônia, que contaminavam o culto."] },
  { r: "Ezequiel 36:26", t: "E dar-vos-ei um coração novo, e porei dentro de vós um espírito novo; e tirarei da vossa carne o coração de pedra, e vos darei um coração de carne.",
    c: "Deus promete transformar o coração do povo exilado, dando-lhe novo espírito.",
    l: ["Coração, no hebraico, designa o centro da vontade e do entendimento, não apenas o órgão físico.",
        "A promessa aponta para uma renovação interior que ultrapassa a simples volta à terra."] },
  { r: "Ezequiel 36:27", t: "E porei dentro de vós o meu Espírito, e farei que andeis nos meus estatutos, e guardeis os meus juízos, e os observeis.",
    c: "Promessa de que o Espírito de Deus capacitará o povo a obedecer aos seus mandamentos.",
    l: ["Estatutos e juízos designam as leis da aliança dadas por meio de Moisés.",
        "A obediência aqui é fruto do Espírito, e não apenas esforço humano."] },
  { r: "Ezequiel 37:5", t: "Assim diz o Senhor Deus a estes ossos: Eis que farei entrar em vós o espírito, e vivereis.",
    c: "Visão do vale de ossos secos, dada a Ezequiel junto ao cativeiro babilônico, retratando a restauração de Israel.",
    l: ["Espírito e sopro traduzem a mesma palavra hebraica ruach, que significa vento, sopro e espírito.",
        "O vale de ossos secos simboliza o povo de Israel dado por morto no exílio."] },
  { r: "Ezequiel 37:14", t: "E porei em vós o meu Espírito, e vivereis, e vos porei na vossa terra; e sabereis que eu, o Senhor, o falei, e o cumprirei, diz o Senhor.",
    c: "Conclusão da visão dos ossos secos, prometendo o retorno dos exilados à sua terra.",
    l: ["A terra prometida era Canaã, à qual os exilados da Babilônia haviam de voltar.",
        "O retorno dos judeus do cativeiro começou sob o decreto de Ciro, rei da Pérsia, em 538 a.C."] },
  { r: "Daniel 2:22", t: "Ele revela o profundo e o escondido; conhece o que está em trevas, e com ele mora a luz.",
    c: "Daniel agradece a revelação do sonho de Nabucodonosor, que nenhum sábio da Babilônia pudera interpretar.",
    l: ["A Babilônia era famosa por seus magos e astrólogos, mas estes não souberam revelar o sonho do rei.",
        "Daniel e seus companheiros haviam sido levados cativos a Babilônia em 605 a.C."] },
  { r: "Daniel 3:17", t: "Eis que o nosso Deus, a quem nós servimos, é que nos pode livrar; ele nos livrará do forno de fogo ardente, e da tua mão, ó rei.",
    c: "Resposta de Sadraque, Mesaque e Abede-Nego ao rei Nabucodonosor, recusando adorar a estátua de ouro.",
    l: ["A fornalha de fogo era usada na Babilônia para fundir metais e calcinar tijolos, atingindo altas temperaturas.",
        "Os três jovens eram judeus deportados, servidores na administração do império babilônico."] },
  { r: "Daniel 6:22", t: "O meu Deus enviou o seu anjo, e fechou a boca dos leões, para que não me fizessem dano, porque foi achada em mim inocência diante dele; e também contra ti, ó rei, não tenho cometido delito algum.",
    c: "Daniel, lançado na cova dos leões por orar a Deus, é preservado durante a noite.",
    l: ["A cova dos leões era um fosso profundo, provavelmente coberto por uma pedra, usado para execução.",
        "A cena ocorre sob o domínio persa, no reinado de Dario, o medo, segundo o relato do livro."] },
  { r: "Daniel 7:14", t: "E foi-lhe dado o domínio, e a honra, e o reino, para que todos os povos, nações e línguas o servissem; o seu domínio é um domínio eterno, que não passará, e o seu reino jamais será destruído.",
    c: "Visão noturna de Daniel sobre o Filho do Homem, que recebe de Deus domínio eterno.",
    l: ["Filho do Homem é expressão aramaica que designa o Messias que recebe o reino de Deus.",
        "Povos, nações e línguas era forma comum de descrever a totalidade dos habitantes do mundo."] },
  { r: "Daniel 9:9", t: "Ao Senhor nosso Deus pertencem as misericórdias e o perdão; porque nos rebelamos contra ele.",
    c: "Daniel ora confessando os pecados de Israel e pedindo misericórdia durante o exílio babilônico.",
    l: ["Daniel orava baseando-se nas profecias de Jeremias sobre os setenta anos de cativeiro.",
        "A oração deste capítulo é uma das mais longas confissões de pecado do Antigo Testamento."] },
  { r: "Daniel 10:19", t: "E disse: Ó homem mui amado, não temas, paz seja contigo; esforça-te, sim, esforça-te. E, falando ele comigo, fui fortalecido, e disse: Fala, meu senhor, porque me fortaleceste.",
    c: "Um anjo fortalece Daniel após a visão junto ao rio Hidequel, no terceiro ano de Ciro, rei da Pérsia.",
    l: ["O rio Hidequel é o Tigre, um dos grandes rios da Mesopotâmia, junto ao qual Daniel teve a visão.",
        "A visão ocorreu no terceiro ano de Ciro, já no fim do exílio babilônico."] },
  { r: "Daniel 12:3", t: "E os que entendem resplandecerão como o fulgor do firmamento; e os que a muitos ensinam a justiça resplandecerão como as estrelas, sempre e eternamente.",
    c: "Encerramento das visões de Daniel, prometendo ressurreição e recompensa aos fiéis.",
    l: ["Resplandecer como as estrelas usa imagem do firmamento, tido no antigo Oriente como sólido e luminoso.",
        "O capítulo fala da ressurreição, tema raro e tardio no Antigo Testamento."] },
  { r: "Oseias 6:3", t: "Então conheçamos, e prossigamos em conhecer ao Senhor; a sua saída é preparada como a alva; e ele descerá sobre nós como a chuva, como a chuva serôdia que rega a terra.",
    c: "Oseias profetiza no reino do Norte, Israel, no século VIII a.C., chamando o povo a voltar-se a Deus.",
    l: ["A chuva serôdia cai em Israel na primavera e era essencial para amadurecer as colheitas.",
        "Oseias viveu pouco antes da queda de Samaria, capital do reino do Norte, em 722 a.C."] },
  { r: "Oseias 10:12", t: "Semeai para vós em justiça, ceifai segundo a misericórdia; lavrai o vosso campo novamente, porque já é tempo de buscar ao Senhor, até que venha e chova a justiça sobre vós.",
    c: "Apelo de Oseias ao arrependimento de Israel, que vivia na idolatria e na injustiça social.",
    l: ["Lavrai o vosso campo usa a imagem do terreno não arado, que precisa ser preparado para a semeadura.",
        "Semear e ceifar eram imagens familiares a um povo agrícola, aplicadas à vida moral."] },
  { r: "Oseias 13:4", t: "Todavia eu sou o Senhor teu Deus desde a terra do Egito; portanto não conhecerás outro deus além de mim, porque não há salvador senão eu.",
    c: "Deus recorda a Israel sua aliança desde o êxodo do Egito, acusando o povo de esquecê-lo.",
    l: ["O Egito era a terra da escravidão de onde Deus libertara Israel no êxodo.",
        "Este é o primeiro dos mandamentos da aliança: não ter outros deuses diante do Senhor."] },
  { r: "Joel 2:13", t: "E rasgai o vosso coração, e não as vossas vestes, e convertei-vos ao Senhor vosso Deus; porque ele é misericordioso, e compassivo, e tardio em irar-se, e grande em beneficência, e se arrepende do mal.",
    c: "Joel chama Judá ao arrependimento após uma praga devastadora de gafanhotos.",
    l: ["Rasgar as vestes era sinal de luto; Joel pede um luto interior, do coração, e não apenas externo.",
        "A praga de gafanhotos é descrita no capítulo anterior como anúncio do dia do Senhor."] },
  { r: "Joel 2:25", t: "E restituir-vos-ei os anos que comeu o gafanhoto, a locusta, e o pulgão, e a lagarta, o meu grande exército que enviei contra vós.",
    c: "Promessa de restauração a Judá depois dos anos consumidos pela praga de gafanhotos.",
    l: ["O gafanhoto e a locusta eram pragas conhecidas no Oriente, capazes de devorar plantações inteiras.",
        "Os nomes citados designam, provavelmente, estágios ou espécies diferentes do mesmo inseto."] },
  { r: "Joel 2:28", t: "E depois disto acontecerá que derramarei o meu Espírito sobre toda a carne; e vossos filhos e vossas filhas profetizarão, vossos velhos sonharão, e vossos jovens terão visões.",
    c: "Anúncio do derramamento do Espírito sobre todo o povo, em contraste com o privilégio de poucos no passado.",
    l: ["No antigo Israel o Espírito era dado a poucos, como reis, sacerdotes e profetas; aqui é prometido a todos.",
        "A promessa abrange filhos, filhas, velhos e jovens, isto é, toda a comunidade."] },
  { r: "Amós 4:12", t: "Portanto, assim te farei, ó Israel; e porque isso te farei, prepara-te, ó Israel, para te encontrares com o teu Deus.",
    c: "Amós, boiadeiro de Tecoa, adverte Israel de que, não tendo voltado a Deus por seus juízos, prepare-se para encontrá-lo.",
    l: ["Tecoa ficava a cerca de 16 km ao sul de Jerusalém, na região montanhosa de Judá.",
        "Amós era criador de gado e cultivava sicômoros antes de ser chamado profeta."] },
  { r: "Amós 5:4", t: "Porque assim diz o Senhor à casa de Israel: Buscai-me, e vivei.",
    c: "Amós exorta o reino do Norte a buscar a Deus, em vez de confiar em seus santuários e cultos.",
    l: ["Israel confiava nos santuários de Betel e Dan; Betel ficava cerca de 18 km ao norte de Jerusalém.",
        "Buscar a Deus, no contexto profético, implicava também praticar a justiça."] },
  { r: "Amós 5:24", t: "Corra, porém, o juízo como as águas, e a justiça como um ribeiro impetuoso.",
    c: "Amós denuncia a injustiça social de Israel, que mantinha o culto mas oprimia os pobres.",
    l: ["Ribeiro impetuoso refere-se ao riacho que corre forte na estação das chuvas.",
        "A imagem pede justiça constante e abundante, como corrente que nunca cessa."] },
  { r: "Amós 9:14", t: "E trarei do cativeiro o meu povo de Israel, e edificarão as cidades assoladas, e as habitarão, e plantarão vinhas, e beberão o seu vinho, e farão pomares, e lhes comerão o fruto.",
    c: "Promessa de restauração de Israel após o juízo, com o retorno do cativeiro.",
    l: ["Vinho e vinhas eram sinais de prosperidade e bênção na vida agrícola de Israel.",
        "Plantar vinha exigia anos de espera, símbolo de segurança duradoura."] },
  { r: "Obadias 1:15", t: "Porque o dia do Senhor está perto, sobre todas as nações: como fizeste, assim se te fará a ti; a tua recompensa voltará sobre a tua cabeça.",
    c: "Obadias anuncia juízo sobre Edom, por se alegrar com a queda de Jerusalém em 586 a.C.",
    l: ["Edom ficava ao sudeste de Judá, na região montanhosa de Seir; seus habitantes descendiam de Esaú.",
        "O dia do Senhor é tema profético do tempo em que Deus julga as nações e instaura seu reino."] },
  { r: "Jonas 2:2", t: "E disse: Na minha angústia clamei ao Senhor, e ele me respondeu; do ventre do sepulcro gritei, e tu ouviste a minha voz.",
    c: "Oração de Jonas de dentro do grande peixe, após fugir de Deus e do chamado para pregar em Nínive.",
    l: ["Sepulcro traduz o hebraico sheol, o mundo dos mortos, imagem de profundidade e morte.",
        "Nínive, destino da missão de Jonas, era a capital do império assírio."] },
  { r: "Jonas 4:2", t: "E orou ao Senhor, e disse: Ah! Senhor! Não foi esta a minha palavra, estando eu ainda na minha terra? Por isso me preveni, fugindo para Társis, pois sabia que és Deus compassivo, e misericordioso, longânimo e grande em benignidade, e que te arrependes do mal.",
    c: "Jonas explica ao Senhor por que fugira para Társis, temendo que Deus poupasse Nínive.",
    l: ["Társis era um porto distante, talvez na península Ibérica, em direção oposta a Nínive.",
        "Nínive ficava às margens do rio Tigre, no atual Iraque, e era tida como cidade muito populosa."] },
  { r: "Miqueias 5:2", t: "Mas tu, Belém Efrata, posto que pequena entre os milhares de Judá, de ti me sairá o que governará em Israel, e cujas saídas são desde os tempos antigos, desde os dias da eternidade.",
    c: "Miqueias, profeta de Morésete, anuncia que o Messias nasceria em Belém, pequena cidade de Judá.",
    l: ["Belém Efrata ficava cerca de 8 km ao sul de Jerusalém e era a cidade de Davi.",
        "Milhares, no hebraico, designava também as famílias ou clãs que formavam as tribos de Israel."] },
  { r: "Miqueias 6:8", t: "Ele te declarou, ó homem, o que é bom; e que é o que o Senhor pede de ti, senão que pratiques a justiça, e ames a misericórdia, e andes humildemente com o teu Deus?",
    c: "Miqueias resume diante de Israel o que Deus realmente pede, em contraste com o culto apenas exterior.",
    l: ["Andar humildemente sugere uma caminhada atenta e atenta diante de Deus, atitude de submissão.",
        "O profeta contrapõe a justiça e a misericórdia aos sacrifícios e ofertas do culto."] },
  { r: "Miqueias 7:18", t: "Quem é Deus semelhante a ti, que perdoa a iniquidade, e que passa por cima da rebelião do restante da sua herança? Ele não retém a sua ira para sempre, porque tem prazer na sua benignidade.",
    c: "Confissão e esperança de Miqueias em nome de Judá, confiando no perdão de Deus.",
    l: ["Passa por cima da rebelião usa a imagem de quem caminha por sobre uma falta, deixando-a para trás.",
        "O nome Miqueias tem som semelhante à pergunta do versículo: quem é como Deus?"] },
  { r: "Naum 1:3", t: "O Senhor é tardio em irar-se, mas grande em força, e ao culpado não tem por inocente; o Senhor tem o seu caminho na tormenta e na tempestade, e as nuvens são o pó dos seus pés.",
    c: "Naum anuncia o juízo de Deus sobre Nínive, capital da Assíria, opressora de Judá.",
    l: ["Nínive ficava às margens do rio Tigre, no atual Iraque, e era a capital do império assírio.",
        "Nuvens e tempestade são imagens usadas nas teofanias, as manifestações de Deus no Antigo Testamento."] },
  { r: "Naum 1:7", t: "O Senhor é bom, uma fortaleza no dia da angústia, e conhece os que confiam nele.",
    c: "Diante da ameaça assíria, Naum afirma que Deus é refúgio para os que nele confiam.",
    l: ["Fortaleza refere-se a uma praça forte, lugar seguro e elevado usado como refúgio contra inimigos.",
        "A Assíria dominou Judá no século VII a.C.; Nínive caiu em 612 a.C., fato celebrado por Naum."] },
  { r: "Habacuque 2:4", t: "Eis que a sua alma orgulhosa não é reta nele; mas o justo pela sua fé viverá.",
    c: "Habacuque questiona Deus sobre a violência em Judá e a ameaça dos babilônios; Deus responde que o justo viverá pela fé.",
    l: ["Os babilônios, chamados caldeus, eram o instrumento do juízo, mas também seriam julgados.",
        "Este versículo é citado várias vezes no Novo Testamento, como em Romanos e Hebreus."] },
  { r: "Habacuque 3:19", t: "O Senhor Deus é a minha força, e fará os meus pés como os das cervas, e me fará andar sobre as minhas alturas.",
    c: "Encerramento do livro como cântico de confiança, ainda que Judá enfrentasse a invasão babilônica.",
    l: ["As cervas, ou corças, são ágeis nas rochas; a imagem descreve firmeza em lugares altos e perigosos.",
        "O capítulo é um salmo, indicado para ser cantado no culto do templo."] },
  { r: "Sofonias 2:3", t: "Buscai ao Senhor, vós todos os mansos da terra, que tendes posto por obra o seu juízo; buscai a justiça, buscai a mansidão; porventura sereis escondidos no dia da ira do Senhor.",
    c: "Sofonias, profeta em Judá no tempo do rei Josias, exorta os humildes a buscar a Deus antes do juízo.",
    l: ["Mansos da terra designa os humildes e oprimidos, que praticavam a justiça em vez da violência.",
        "O ministério de Sofonias situa-se no século VII a.C., antes da reforma religiosa de Josias."] },
  { r: "Sofonias 3:17", t: "O Senhor teu Deus está no meio de ti, poderoso te salvará; ele se deleitará em ti com alegria; calar-se-á por seu amor, regozijar-se-á em ti com júbilo.",
    c: "Promessa de restauração a Jerusalém após o juízo, com Deus habitando no meio do povo.",
    l: ["No meio de ti indica a presença de Deus no meio de seu povo, tema central do culto de Sião.",
        "Sião era o monte de Jerusalém onde ficava o templo, símbolo da morada de Deus."] },
  { r: "Ageu 1:8", t: "Subi ao monte, e trazei madeira, e edificai a casa; e dela me agradarei, e serei glorificado, diz o Senhor.",
    c: "Ageu exorta os judeus que voltaram do exílio a reconstruir o templo, obra parada por cerca de dezesseis anos.",
    l: ["O templo de Jerusalém fora destruído em 586 a.C.; a reconstrução foi retomada em 520 a.C. sob Ageu e Zacarias.",
        "Subi ao monte refere-se aos montes ao redor de Jerusalém, de onde se tirava madeira para a obra."] },
  { r: "Ageu 2:9", t: "A glória desta última casa será maior do que a da primeira, diz o Senhor dos Exércitos, e neste lugar darei a paz, diz o Senhor dos Exércitos.",
    c: "Ageu encoraja o povo e Zorobabel, governador, prometendo glória maior ao novo templo.",
    l: ["Zorobabel era governador de Judá e descendente de Davi; liderou a reconstrução do templo.",
        "Senhor dos Exércitos é título divino que apresenta Deus como comandante dos exércitos celestes."] },
  { r: "Zacarias 4:6", t: "E respondeu, e falou-me, dizendo: Esta é a palavra do Senhor a Zorobabel, dizendo: Não por força nem por violência, mas sim pelo meu Espírito, diz o Senhor dos Exércitos.",
    c: "Zacarias anima Zorobabel com a visão do candelabro, afirmando que a obra se fará pelo Espírito de Deus.",
    l: ["O candelabro, ou menorá, era um candelabro de ouro de sete braços usado no templo.",
        "Zacarias profetizou junto com Ageu no período da reconstrução do templo, após o exílio."] },
  { r: "Zacarias 9:9", t: "Alegra-te muito, ó filha de Sião; exulta, ó filha de Jerusalém; eis que o teu rei virá a ti, justo e Salvador, pobre, e montado sobre um jumento, e sobre um jumentinho, filho de jumenta.",
    c: "Anúncio da vinda do rei messiânico a Jerusalém, humilde e montado num jumentinho.",
    l: ["A filha de Sião é forma poética de designar Jerusalém, a cidade de Deus.",
        "Montar um jumentinho, e não um cavalo de guerra, indicava vinda pacífica e humilde."] },
  { r: "Zacarias 12:10", t: "E derramarei sobre a casa de Davi, e sobre os habitantes de Jerusalém, o Espírito de graça e de súplicas; e olharão para mim, a quem traspassaram; e prantearão sobre ele, como quem chora por um filho unigênito, e estarão em amargura por ele, como quem está de luto pelo primogênito.",
    c: "Oráculo sobre Jerusalém, prometendo o derramamento de graça e o lamento por aquele que foi traspassado.",
    l: ["A casa de Davi designa a dinastia real de Judá, que governava de Jerusalém.",
        "Prantear pelo primogênito era luto profundo, pois o primogênito tinha lugar especial na família e na herança."] },
  { r: "Zacarias 13:1", t: "Naquele dia haverá uma fonte aberta para a casa de Davi, e para os habitantes de Jerusalém, contra o pecado e contra a imundície.",
    c: "Promessa de purificação da casa de Davi e dos habitantes de Jerusalém.",
    l: ["Fonte, aqui, é nascente de água, que limpava a imundície e o pecado conforme os ritos do templo.",
        "A casa de Davi e Jerusalém representam todo o povo da aliança."] },
  { r: "Zacarias 14:9", t: "E o Senhor será rei sobre toda a terra; naquele dia um será o Senhor, e um será o seu nome.",
    c: "Conclusão do livro, que descreve o reinado universal de Deus sobre toda a terra.",
    l: ["O dia do Senhor é tema profético do tempo em que Deus julga e instaura seu reino.",
        "Um será o Senhor afirma a unicidade de Deus sobre todas as nações."] },
  { r: "Malaquias 3:6", t: "Porque eu, o Senhor, não mudo; por isso vós, ó filhos de Jacó, não sois consumidos.",
    c: "Malaquias, último profeta do Antigo Testamento, responde ao povo que duvidava do amor de Deus.",
    l: ["Não mudo expressa a constância de Deus; por isso Israel, apesar de suas faltas, não foi destruído.",
        "Filhos de Jacó é designação de todo o povo de Israel, descendente do patriarca Jacó."] },
  { r: "Malaquias 3:8", t: "Roubará o homem a Deus? Todavia vós me roubais, e dizeis: Em que te roubamos? Nos dízimos e nas ofertas.",
    c: "Deus repreende o povo por sonegar dízimos e ofertas, negligenciando o sustento do templo.",
    l: ["Os dízimos eram a décima parte das colheitas e do gado, destinada ao sustento dos levitas e do templo.",
        "As ofertas eram contribuições trazidas ao santuário, além dos dízimos."] },
  { r: "Malaquias 3:10", t: "Trazei todos os dízimos à casa do tesouro, para que haja mantimento na minha casa, e depois fazei prova de mim nisto, diz o Senhor dos Exércitos, se eu não vos abrir as janelas do céu, e não derramar sobre vós uma bênção tal até que não haja lugar suficiente para a recolherdes.",
    c: "Convite de Deus a Israel a trazer os dízimos e experimentar sua bênção sobre o templo e o povo.",
    l: ["A casa do tesouro era o depósito do templo, onde se guardavam mantimentos e dízimos.",
        "Aberta as janelas do céu é imagem da chuva abundante que fazia prosperar as colheitas."] },
  { r: "Malaquias 3:16", t: "Então aqueles que temiam ao Senhor falaram cada um ao seu companheiro; e o Senhor atentou e ouviu, e um memorial foi escrito diante dele, para os que temiam ao Senhor, e para os que se lembravam do seu nome.",
    c: "Malaquias registra que os que temiam a Deus se animavam mutuamente, e Deus os ouvia.",
    l: ["O memorial era um registro escrito, imagem de que Deus se lembra dos fiéis.",
        "Temer ao Senhor, no Antigo Testamento, é respeitar e obedecer a Deus com reverência."] },
  { r: "Malaquias 4:2", t: "Mas para vós, os que temeis o meu nome, nascerá o sol da justiça, e cura trará nas suas asas; e saireis e saltareis como bezerros da estrebaria.",
    c: "Promessa final do Antigo Testamento, de um sol de justiça para os que temem a Deus.",
    l: ["Bezerros da estrebaria eram animais soltos após dias presos, imagem de alegria e liberdade.",
        "As asas do sol são imagem poética dos raios que trazem cura e vida."] },
{ r: "Mateus 3:17", t: "E eis que uma voz dos céus dizia: Este é o meu Filho amado, em quem me comprazo.",
    c: "Mateus escreve a judeus-cristãos apresentando Jesus como o Messias prometido. No batismo de Jesus, no rio Jordão, a voz do Pai o confirma publicamente como Filho amado.",
    l: ["O Jordão é o principal rio da Terra de Israel; Jesus foi batizado por João numa região sua, perto de Betânia, além do Jordão.",
        "“Comprazo” traduz o grego eudokésa, que indica satisfação e deleite plenos do Pai no Filho."] },
  { r: "Mateus 5:14", t: "Vós sois a luz do mundo; não se pode esconder uma cidade edificada sobre um monte.",
    c: "Na abertura do Sermão do Monte, Jesus ensina aos discípulos o caráter do reino de Deus e a missão de testemunhar diante do mundo.",
    l: ["Jesus falou provavelmente numa colina junto ao mar da Galileia; à noite, uma cidade sobre um monte era visível de longe pela luz de suas casas.",
        "“Mundo” traduz o grego kósmos, a ordem criada e a humanidade nela."] },
  { r: "Mateus 6:33", t: "Mas buscai primeiro o reino de Deus, e a sua justiça, e todas estas coisas vos serão acrescentadas.",
    c: "No Sermão do Monte, Jesus ensina seus seguidores a confiar no Pai em vez de andarem ansiosos pelas necessidades materiais da vida.",
    l: ["O contexto trata de comida, bebida e vestes, bens básicos de subsistência no mundo antigo.",
        "“Reino de Deus” designa o governo soberano de Deus, inaugurado em Cristo e ainda a consumar-se."] },
  { r: "Mateus 11:28", t: "Vinde a mim, todos os que estais cansados e oprimidos, e eu vos aliviarei.",
    c: "Jesus fala após denunciar cidades que não se arrependeram e conclama os sobrecarregados a virem a Ele para receberem descanso.",
    l: ["“Oprimidos” evoca o peso de cargas, imagem comum para o jugo da lei e as aflições da vida.",
        "“Aliviar” traduz o grego anapáuo, dar descanso e refrigério."] },
  { r: "Mateus 24:35", t: "O céu e a terra passarão, mas as minhas palavras não hão de passar.",
    c: "No sermão profético, no monte das Oliveiras, Jesus fala a seus discípulos sobre os últimos tempos e a certeza de suas palavras.",
    l: ["Jesus estava no monte das Oliveiras, defronte de Jerusalém, do outro lado do vale do Cedrom.",
        "“Céu e terra” abrange toda a ordem criada, que Deus pode desfazer."] },
  { r: "Mateus 28:19", t: "Portanto ide, ensinai todas as nações, batizando-as em nome do Pai, e do Filho, e do Espírito Santo.",
    c: "Antes de subir ao céu, o Cristo ressurreto comissiona os discípulos na Galileia a fazerem discípulos em todo o mundo.",
    l: ["“Nações” traduz o grego éthnos, os povos e etnias; a missão ultrapassa as fronteiras de Israel.",
        "“Batizar” vem do grego baptízo, imergir; era o rito de ingresso na comunidade cristã."] },
  { r: "Marcos 1:15", t: "E dizendo: O tempo está cumprido, e o reino de Deus está próximo; arrependei-vos, e crede no evangelho.",
    c: "Marcos, companheiro de Pedro, abre seu evangelho apresentando Jesus proclamando em Cafarnaum a chegada do reino.",
    l: ["“Arrepender-se” traduz metanoéo, mudar de mente e de rumo diante de Deus.",
        "“Evangelho” significa boas-novas e refere-se à boa notícia do reino em Cristo."] },
  { r: "Marcos 8:36", t: "Pois que aproveita ao homem ganhar o mundo inteiro, e perder a sua alma?",
    c: "Jesus alerta seus discípulos sobre o custo de segui-lo, após anunciar sua paixão e morte.",
    l: ["“Alma” traduz o grego psyqué, a vida inteira da pessoa; aqui significa a própria vida eterna do ser.",
        "“Mundo” designa kósmos, os bens e a ordem deste século."] },
  { r: "Marcos 10:45", t: "Porque o Filho do homem também não veio para ser servido, mas para servir, e para dar a sua vida em resgate de muitos.",
    c: "Jesus corrige a ambição de Tiago e João, que pediam lugares de honra, e ensina a lógica do serviço.",
    l: ["“Filho do homem” é o título que Jesus mais usa de si, ligado a Daniel 7 e à sua missão.",
        "“Resgate” traduz lýtron, o preço que liberta um cativo ou escravo."] },
  { r: "Marcos 12:31", t: "E o segundo, semelhante a este, é: Amarás o teu próximo como a ti mesmo. Não há outro mandamento maior do que estes.",
    c: "Questionado por um escriba sobre o maior mandamento, Jesus resume a lei no amor a Deus e ao próximo.",
    l: ["“Próximo” traduz o grego plesíon, o que está perto, sem limite étnico ou social.",
        "Jesus une Deuteronômio 6:5 e Levítico 19:18, ligando piedade e ética."] },
  { r: "Marcos 16:15", t: "E disse-lhes: Ide por todo o mundo, pregai o evangelho a toda criatura.",
    c: "O Cristo ressurreto aparece aos onze e os envia a proclamar o evangelho a toda a criação.",
    l: ["“Criatura” traduz ktísis, o que foi criado; a mensagem destina-se a todos os povos.",
        "Este é o final mais longo de Marcos, atestado em antigos manuscritos gregos."] },
  { r: "Lucas 2:11", t: "Pois hoje vos nasceu, na cidade de Davi, o Salvador, que é Cristo, o Senhor.",
    c: "Lucas, médico e companheiro de Paulo, escreve um relato ordenado a Teófilo; aqui anuncia o nascimento de Jesus a pastores em Belém.",
    l: ["“Cristo” traduz o hebraico Messias, o ungido; “Salvador” traduz sotér.",
        "Belém, a cidade de Davi, fica cerca de 8 km ao sul de Jerusalém."] },
  { r: "Lucas 15:7", t: "Digo-vos que assim haverá alegria no céu por um pecador que se arrepende, mais do que por noventa e nove justos que não necessitam de arrependimento.",
    c: "Jesus conta a parábola da ovelha perdida em resposta às críticas dos fariseus por receber pecadores.",
    l: ["As noventa e nove ovelhas representam os que se julgam justos, em contraste com o perdido.",
        "Deixar o rebanho reflete o cuidado diário dos pastores da Judeia com cada ovelha."] },
  { r: "Lucas 19:10", t: "Porque o Filho do homem veio buscar e salvar o que se havia perdido.",
    c: "Jesus declara isso na casa de Zaqueu, em Jericó, explicando por que se hospedara com um publicano.",
    l: ["Jericó é um dos lugares habitados mais antigos conhecidos, no vale do Jordão.",
        "“Publicano” era o cobrador de impostos a serviço de Roma, desprezado pelos judeus."] },
  { r: "Lucas 23:34", t: "E dizia Jesus: Pai, perdoa-lhes, porque não sabem o que fazem. E, repartindo os seus vestidos, lançaram sortes.",
    c: "Na crucificação, fora dos muros de Jerusalém, Jesus intercede pelos que o executam, cumprindo a profecia do Salmo 22.",
    l: ["“Lançar sortes” era tirar a sorte para repartir bens, prática comum entre soldados romanos.",
        "A crucificação era a pena romana reservada a escravos e rebeldes, executada fora da cidade."] },
  { r: "Lucas 24:6", t: "Não está aqui, mas ressuscitou. Lembrai-vos de como vos falou, estando ainda na Galileia.",
    c: "Mulheres chegam ao sepulcro vazio no primeiro dia da semana e são lembradas por anjos do que Jesus havia predito.",
    l: ["O sepulcro estava numa cova escavada na rocha, fechada por uma pedra circular.",
        "A Galileia, região ao norte, foi onde Jesus mais atuou e onde anunciou sua ressurreição."] },
  { r: "João 1:1", t: "No princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus.",
    c: "João, o discípulo amado, abre seu evangelho afirmando a divindade eterna de Cristo como o Verbo de Deus.",
    l: ["“Verbo” traduz o grego Lógos, a Palavra divina, pela qual Deus cria e se revela.",
        "“No princípio” ecoa Gênesis 1:1, ligando a criação à pessoa de Cristo."] },
  { r: "João 3:16", t: "Porque Deus amou o mundo de tal maneira que deu o seu Filho unigênito, para que todo aquele que nele crê não pereça, mas tenha a vida eterna.",
    c: "Jesus conversa à noite com Nicodemos, um mestre de Israel, e explica o amor de Deus como origem da salvação.",
    l: ["“Unigênito” traduz o grego monogenés, que indica único e singular, não apenas o primeiro de vários.",
        "Nicodemos era fariseu e membro do Sinédrio, o conselho supremo de Jerusalém."] },
  { r: "João 8:32", t: "E conhecereis a verdade, e a verdade vos libertará.",
    c: "Jesus fala aos judeus que creram nele, exortando-os a permanecer na sua palavra como verdadeiros discípulos.",
    l: ["“Verdade” traduz alétheia, o que é real e confiável, em oposição à aparência.",
        "“Libertar” traduz eleutheróo, dar a liberdade ao escravo."] },
  { r: "João 10:10", t: "O ladrão não vem senão a roubar, a matar, e a destruir; eu vim para que tenham vida, e a tenham com abundância.",
    c: "Jesus usa a figura do pastor e das ovelhas para contrastar-se com os falsos líderes e apresentar-se como fonte de vida.",
    l: ["O aprisco de ovelhas na Palestina era um cercado de pedras com uma única porta vigiada.",
        "“Abundância” traduz o grego perissón, em medida transbordante."] },
  { r: "João 11:25", t: "Disse-lhe Jesus: Eu sou a ressurreição e a vida; quem crê em mim, ainda que esteja morto, viverá.",
    c: "Antes de ressuscitar Lázaro, em Betânia, Jesus consola Marta com a promessa da ressurreição.",
    l: ["Betânia ficava cerca de três quilômetros de Jerusalém, além do monte das Oliveiras.",
        "“Eu sou” é a fórmula com que Jesus revela sua identidade divina."] },
  { r: "João 14:6", t: "Disse-lhe Jesus: Eu sou o caminho, e a verdade e a vida; ninguém vem ao Pai, senão por mim.",
    c: "Na última ceia, Jesus responde a Tomé, consolando os discípulos diante de sua partida.",
    l: ["“Caminho” traduz hodós, rota ou via; Jesus é o acesso ao Pai.",
        "A ceia ocorreu em Jerusalém, provavelmente num cenáculo, na véspera da crucificação."] },
  { r: "Atos 1:8", t: "Mas receberéis a virtude do Espírito Santo, quando ele descer sobre vós; e ser-me-eis testemunhas tanto em Jerusalém como em toda a Judeia e Samaria, e até aos confins da terra.",
    c: "Antes de ascender, Jesus promete o Espírito e define o alcance do testemunho cristão, expressando o plano do livro de Atos.",
    l: ["A Judeia fica ao sul de Samaria; Samaria estava entre a Judeia e a Galileia.",
        "“Confins da terra” aponta para Roma e as nações gentílicas."] },
  { r: "Atos 2:38", t: "E disse-lhes Pedro: Arrependei-vos, e cada um de vós seja batizado em nome de Jesus Cristo, para perdão dos pecados; e recebereis o dom do Espírito Santo.",
    c: "No dia de Pentecostes, Pedro prega à multidão em Jerusalém e responde à pergunta dos que foram tocados pelo sermão.",
    l: ["Pentecostes era a festa judaica das semanas, celebrada cinquenta dias após a Páscoa.",
        "Jerusalém reunia peregrinos de muitas nações, o que explica as línguas citadas no capítulo."] },
  { r: "Atos 4:12", t: "E em nenhum outro há salvação, porque também debaixo do céu nenhum outro nome há, dado entre os homens, pelo qual devamos ser salvos.",
    c: "Pedro e João, diante do Sinédrio, testemunham após curar um coxo à porta do templo.",
    l: ["O Sinédrio era o tribunal supremo dos judeus, com autoridade religiosa e civil.",
        "“Salvação” traduz soteria, livramento e cura em sentido integral."] },
  { r: "Atos 16:31", t: "E eles disseram: Crê no Senhor Jesus Cristo e serás salvo, tu e a tua casa.",
    c: "Paulo e Silas, presos em Filipos, respondem ao carcereiro que pergunta o que deve fazer para ser salvo.",
    l: ["Filipos era cidade romana na Macedônia, colônia com muitos veteranos e sem sinagoga.",
        "“Casa” incluía a família e o lar, unidade básica da sociedade antiga."] },
  { r: "Romanos 1:16", t: "Porque não me envergonho do evangelho de Cristo, pois é o poder de Deus para salvação de todo aquele que crê; primeiro do judeu, e também do grego.",
    c: "Paulo escreve à igreja de Roma, expondo o evangelho que prega, antes de visitá-la.",
    l: ["“Grego” aqui representa os gentios, os não judeus de cultura greco-romana.",
        "“Poder” traduz dýnamis, de onde vem a palavra dinamite."] },
  { r: "Romanos 3:23", t: "Porque todos pecaram e destituídos estão da glória de Deus.",
    c: "Paulo argumenta que judeus e gentios estão igualmente debaixo do pecado e necessitam da justificação em Cristo.",
    l: ["“Destituídos” significa privados de alcançar ou de estar à altura da glória de Deus.",
        "“Glória” traduz dóxa, o esplendor e a honra próprios de Deus."] },
  { r: "Romanos 6:23", t: "Porque o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna, por Cristo Jesus nosso Senhor.",
    c: "Paulo contrasta a escravidão ao pecado com a nova vida em Cristo, exortando os crentes à santidade.",
    l: ["“Salário” traduz opsónion, o pagamento devido ao soldado romano.",
        "“Dom” traduz chárisma, dádiva gratuita e imerecida."] },
  { r: "Romanos 8:28", t: "E sabemos que todas as coisas contribuem juntamente para o bem daqueles que amam a Deus, daqueles que são chamados segundo o seu propósito.",
    c: "Paulo trata do sofrimento presente dos crentes diante da glória futura, assegurando o cuidado de Deus.",
    l: ["“Propósito” traduz próthesis, plano determinado de antemão por Deus.",
        "O capítulo 8 é o clímax da exposição paulina sobre a vida no Espírito."] },
  { r: "1 Coríntios 6:19", t: "Ou não sabeis que o vosso corpo é o templo do Espírito Santo, que habita em vós, proveniente de Deus, e que não sois de vós mesmos?",
    c: "Paulo exorta os coríntios a fugirem da imoralidade sexual, fundamentando o dever na presença do Espírito.",
    l: ["“Templo” traduz naós, o santuário interior, não apenas o pátio do edifício.",
        "A metáfora ecoa os templos de Corinto, onde se esperava reverência ao sagrado."] },
  { r: "1 Coríntios 10:13", t: "Não vos sobreveio tentação que não fosse humana; mas Deus é fiel, e não permitirá que sejais tentados além das vossas forças; antes, com a tentação proverá também o escape, para que a possais suportar.",
    c: "Paulo adverte a igreja de Corinto, cercada de idolatria, exortando à firmeza e à confiança em Deus.",
    l: ["“Tentação” traduz peirasmós, prova ou solicitação ao pecado.",
        "Corinto era porto próspero e famoso por seus templos pagãos e sua imoralidade."] },
  { r: "1 Coríntios 13:4", t: "O amor é sofredor, é benigno; o amor não é invejoso; o amor não trata com leviandade, não se ensoberbece.",
    c: "No chamado hino ao amor, Paulo corrige a busca de dons espetaculares na igreja de Corinto.",
    l: ["“Amor” traduz agápe, o amor de entrega e benevolência, não o mero afeto.",
        "“Sofredor” significa paciente; “benigno” significa bondoso e útil."] },
  { r: "1 Coríntios 15:3", t: "Porque primeiramente vos entreguei o que também recebi: que Cristo morreu por nossos pecados, segundo as Escrituras.",
    c: "Paulo recorda o cerne do evangelho que pregou em Corinto, base da fé dos crentes.",
    l: ["“Segundo as Escrituras” aponta para o Antigo Testamento e suas profecias messiânicas.",
        "Paulo fundou a igreja de Corinto em sua segunda viagem missionária."] },
  { r: "2 Coríntios 4:18", t: "Não atentando nós nas coisas que se veem, mas nas que se não veem; porque as que se veem são temporais, e as que se não veem são eternas.",
    c: "Paulo encoraja os crentes a fixarem a esperança no que é eterno, em meio às aflições passageiras.",
    l: ["“Temporal” traduz próskairos, o que dura pouco tempo.",
        "“Eterno” traduz aiónios, o que pertence à era vindoura."] },
  { r: "2 Coríntios 5:17", t: "Assim que, se alguém está em Cristo, nova criatura é; as coisas velhas já passaram; eis que tudo se fez novo.",
    c: "Paulo descreve a transformação operada pela reconciliação em Cristo, encorajando os crentes de Corinto.",
    l: ["“Nova criatura” traduz kainé ktísis, criação de espécie nova, não mera reforma.",
        "“Eis” é marca de linguagem hebraica que enfatiza e introduz algo notável."] },
  { r: "2 Coríntios 12:9", t: "E disse-me: A minha graça te basta, porque o meu poder se aperfeiçoa na fraqueza. De boa vontade, pois, me gloriarei nas minhas fraquezas, para que em mim habite o poder de Cristo.",
    c: "Paulo narra a resposta de Deus ao seu pedido sobre o espinho na carne, mostrando a força que vem da fraqueza.",
    l: ["“Graça” traduz cháris, favor imerecido concedido por Deus.",
        "“Espinho” sugere uma enfermidade ou oposição persistente que Paulo não nomeia."] },
  { r: "Gálatas 2:20", t: "Já estou crucificado com Cristo; e vivo, não mais eu, mas Cristo vive em mim; e a vida que agora vivo na carne, vivo-a pela fé do Filho de Deus, o qual me amou, e se entregou a si mesmo por mim.",
    c: "Paulo defende a justificação pela fé, mostrando que a lei o levou a morrer para a lei e viver para Deus.",
    l: ["“Crucificado com Cristo” indica a união do crente com a morte de Cristo, rompendo a antiga vida.",
        "Gálatas eram igrejas da região da Galácia, na atual Turquia central."] },
  { r: "Gálatas 5:22", t: "Mas o fruto do Espírito é: caridade, gozo, paz, longanimidade, benignidade, bondade, fé, mansidão, temperança.",
    c: "Paulo contrasta as obras da carne com o fruto do Espírito, defendendo a vida guiada pelo Espírito e não pela lei.",
    l: ["“Fruto” está no singular, indicando um conjunto único de virtudes, não uma lista de dons isolados.",
        "“Longanimidade” significa paciência que suporta longamente sem se irritar."] },
  { r: "Efésios 2:8", t: "Porque pela graça sois salvos, por meio da fé; e isto não vem de vós, é dom de Deus.",
    c: "Paulo exalta a salvação concedida gratuitamente, contrastando-a com as obras, para excluir a vanglória.",
    l: ["“Graça” traduz cháris, favor imerecido; chárisma é o dom correspondente.",
        "Éfeso era grande cidade da Ásia Menor, com o famoso templo de Ártemis."] },
  { r: "Efésios 6:11", t: "Revesti-vos de toda a armadura de Deus, para que possais estar firmes contra as astutas ciladas do diabo.",
    c: "Paulo, possivelmente preso, exorta os crentes a se fortalecerem no Senhor para resistir ao mal.",
    l: ["As peças citadas a seguir, como cinto, couraça, sandálias, escudo, capacete e espada, refletem a panóplia do soldado romano.",
        "“Diabo” traduz diábolos, o acusador e adversário."] },
  { r: "Filipenses 4:6", t: "Não estejais inquietos por coisa alguma; antes as vossas petições sejam em tudo conhecidas diante de Deus pela oração e súplica, com ação de graças.",
    c: "Paulo exorta os filipenses a trocarem a ansiedade pela oração confiante, resultado da paz de Deus.",
    l: ["“Súplica” traduz déesis, pedido insistente feito em favor de alguém.",
        "“Ação de graças” traduz eucharistía, gratidão que acompanha o pedido."] },
  { r: "Filipenses 4:13", t: "Posso todas as coisas em Cristo que me fortalece.",
    c: "Paulo agradece o auxílio dos filipenses e afirma sua confiança em Cristo tanto na abundância quanto na escassez.",
    l: ["“Todas as coisas” refere-se às circunstâncias da vida, não a qualquer empreendimento.",
        "Filipos foi a primeira igreja fundada por Paulo na Europa."] },
  { r: "Colossenses 1:16", t: "Porque nele foram criadas todas as coisas que há nos céus e na terra, visíveis e invisíveis, sejam tronos, sejam dominações, sejam principados, sejam potestades. Tudo foi criado por ele e para ele.",
    c: "Paulo apresenta a supremacia de Cristo sobre toda a criação, refutando ensinos que rebaixavam o Filho.",
    l: ["“Tronos”, “dominações”, “principados” e “potestades” designam hierarquias espirituais da cosmovisão antiga.",
        "“Por ele e para ele” afirma Cristo como agente e finalidade da criação."] },
  { r: "Colossenses 3:23", t: "E, tudo quanto fizerdes, fazei-o de todo o coração, como ao Senhor, e não aos homens.",
    c: "Paulo orienta os crentes de Colossos sobre a vida familiar e o trabalho, referindo tudo a Cristo.",
    l: ["Colossos ficava no vale do rio Lico, na Ásia Menor, perto de Laodiceia e Hierápolis.",
        "“De todo o coração” traduz ek psyqués, com toda a alma, isto é, com dedicação plena."] },
  { r: "1 Tessalonicenses 4:16", t: "Porque o mesmo Senhor descerá do céu com alarido, e com voz de arcanjo, e com a trombeta de Deus; e os que morreram em Cristo ressuscitarão primeiro.",
    c: "Paulo consola os tessalonicenses a respeito dos que morreram, ensinando sobre a vinda do Senhor.",
    l: ["“Alarido” traduz kéleusma, ordem ou grito de comando militar.",
        "Tessalônica era capital da Macedônia, situada na importante via Egnácia."] },
  { r: "1 Tessalonicenses 5:17", t: "Orai sem cessar.",
    c: "Na conclusão da carta, Paulo dá breves exortações à vida cristã: alegrar-se, orar e dar graças em tudo.",
    l: ["“Sem cessar” traduz adialeíptos, de modo contínuo e constante.",
        "A oração constante era prática central das comunidades cristãs primitivas."] },
  { r: "2 Tessalonicenses 3:3", t: "Mas fiel é o Senhor, que vos confirme e guarde do mal.",
    c: "Paulo, escrevendo após notícias de perseguição e confusão sobre a vinda do Senhor, anima os crentes com a fidelidade de Deus.",
    l: ["“Guardar” traduz phylásso, proteger como uma sentinela guarda um posto.",
        "Esta é a segunda carta de Paulo à igreja de Tessalônica, pouco depois da primeira."] },
  { r: "1 Timóteo 2:5", t: "Porque há um só Deus, e um só Mediador entre Deus e os homens, Jesus Cristo homem.",
    c: "Paulo instrui Timóteo, líder na igreja de Éfeso, sobre a oração por todos os homens e a mediação de Cristo.",
    l: ["“Mediador” traduz mesítes, aquele que se interpõe entre duas partes.",
        "Timóteo era jovem colaborador de Paulo, deixado em Éfeso para dirigir a igreja."] },
  { r: "1 Timóteo 6:10", t: "Porque o amor ao dinheiro é a raiz de todos os males; e nessa cobiça alguns se desviaram da fé, e se traspassaram a si mesmos com muitas dores.",
    c: "Paulo adverte contra o falso ensino movido por ganho financeiro, exortando Timóteo à piedade com contentamento.",
    l: ["A frase não afirma que o dinheiro em si seja mau, mas o amor a ele.",
        "“Cobiça” traduz pleonexía, desejo desordenado de ter sempre mais."] },
  { r: "2 Timóteo 3:16", t: "Toda a Escritura é divinamente inspirada, e proveitosa para ensinar, para redarguir, para corrigir, para instruir em justiça.",
    c: "Paulo, na sua última carta, escreve ao jovem Timóteo sobre o valor das Escrituras diante dos tempos difíceis.",
    l: ["“Inspirada” traduz theópneustos, soprada por Deus.",
        "“Escritura” refere-se aos textos sagrados do Antigo Testamento, então já formados."] },
  { r: "2 Timóteo 4:7", t: "Combati o bom combate, acabei a carreira, guardei a fé.",
    c: "Paulo, próximo do fim da vida, resume seu ministério e encoraja Timóteo a continuar fiel.",
    l: ["As imagens do combate e da corrida eram familiares aos gregos, que tinham os jogos atléticos.",
        "“Guardar a fé” significa conservar intacto o depósito da doutrina recebida."] },
  { r: "Tito 2:11", t: "Porque a graça de Deus se há manifestado, trazendo salvação a todos os homens.",
    c: "Paulo escreve a Tito, encarregado das igrejas em Creta, sobre a conduta dos crentes diante do mundo.",
    l: ["Creta é uma grande ilha do Mediterrâneo, ao sul do mar Egeu, habitada por diversos povos.",
        "“Manifestado” traduz epipháneia, o aparecimento visível e glorioso da graça."] },
  { r: "Filemom 1:16", t: "Não como escravo; antes, muito melhor do que escravo, como irmão amado, particularmente de mim, e quanto mais de ti, tanto na carne como no Senhor?",
    c: "Paulo envia de volta o escravo fugitivo Onésimo, pedindo a Filemom que o receba como irmão em Cristo.",
    l: ["A escravidão era instituição difundida no Império Romano; escravos fugidos podiam ser severamente punidos.",
        "Filemom morava provavelmente em Colossos, e a carta é um bilhete pessoal de Paulo."] },
  { r: "Hebreus 4:12", t: "Porque a palavra de Deus é viva e eficaz, e mais penetrante do que qualquer espada de dois fios, e penetra até à divisão da alma, e do espírito, e das juntas e medulas, e é apta para discernir os pensamentos e intenções do coração.",
    c: "O autor anônimo exorta os crentes a não endurecerem o coração, mostrando o poder da palavra de Deus.",
    l: ["“Espada de dois fios” era arma romana curta, afiada dos dois lados, capaz de cortar ao penetrar.",
        "“Juntas e medulas” representam as partes mais profundas do ser humano."] },
  { r: "Hebreus 11:1", t: "Ora, a fé é o firme fundamento das coisas que se esperam, e a prova das coisas que se não veem.",
    c: "Antes da grande galeria de heróis da fé, o autor define a fé como base da vida agradável a Deus.",
    l: ["“Firme fundamento” traduz hypóstasis, aquilo que está por baixo e sustenta.",
        "O capítulo 11 percorre personagens do Antigo Testamento como exemplos de fé."] },
  { r: "Hebreus 12:2", t: "Olhando para Jesus, autor e consumador da fé, o qual, pelo gozo que lhe estava proposto, suportou a cruz, desprezando a afronta, e assentou-se à destra do trono de Deus.",
    c: "O autor exorta a correr com paciência, fixando os olhos em Jesus, exemplo supremo de perseverança.",
    l: ["“Autor” traduz archegós, o pioneiro que abre o caminho.",
        "Sentar-se à destra do trono simboliza a posição de honra e autoridade suprema."] },
  { r: "Hebreus 13:8", t: "Jesus Cristo é o mesmo, ontem, e hoje, e eternamente.",
    c: "No fecho da carta, o autor afirma a constância de Cristo como alicerce da fé em meio a ensinos variados.",
    l: ["A expressão abrange passado, presente e futuro, afirmando a imutabilidade de Cristo.",
        "Hebreus foi escrito a cristãos de origem judaica tentados a voltar ao judaísmo."] },
  { r: "Tiago 1:5", t: "E, se algum de vós tem falta de sabedoria, peça-a a Deus, que a todos dá liberalmente, e o não lança em rosto, e ser-lhe-á dada.",
    c: "Tiago, líder da igreja em Jerusalém, exorta os crentes dispersos a buscarem sabedoria na provação.",
    l: ["“Não lança em rosto” significa não censurar nem reprochar quem pede.",
        "“Sabedoria” traduz sophía, a habilidade de viver retamente diante de Deus."] },
  { r: "Tiago 2:17", t: "Assim também a fé, se não tiver as obras, é morta em si mesma.",
    c: "Tiago corrige uma fé meramente verbal, mostrando que a fé verdadeira se comprova por obras concretas.",
    l: ["“Morta” indica algo inoperante e sem vida, não aniquilado.",
        "Tiago escreve às doze tribos dispersas, judeus-cristãos fora da Palestina."] },
  { r: "1 Pedro 1:3", t: "Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, que, segundo a sua grande misericórdia, nos gerou de novo para uma viva esperança, pela ressurreição de Jesus Cristo dentre os mortos.",
    c: "Na abertura da carta, Pedro louva a Deus pela nova vida e pela esperança garantida pela ressurreição.",
    l: ["“Gerou de novo” traduz anagennáo, dar novo nascimento espiritual.",
        "Pedro escreve a cristãos dispersos na Ásia Menor, provavelmente desde Roma."] },
  { r: "1 Pedro 2:24", t: "Levando ele mesmo em seu corpo os nossos pecados sobre o madeiro, para que, mortos para os pecados, pudéssemos viver para a justiça; e pelas suas feridas fostes sarados.",
    c: "Pedro apresenta Cristo como exemplo de sofrimento paciente, citando a figura do servo sofredor de Isaías 53.",
    l: ["“Madeiro” traduz xýlon, termo usado para a cruz de madeira.",
        "A citação de Isaías 53 liga a cura à expiação realizada na cruz."] },
  { r: "1 Pedro 5:7", t: "Lançando sobre ele toda a vossa ansiedade, porque ele tem cuidado de vós.",
    c: "Pedro encoraja os crentes que sofrem perseguição a humilhar-se diante de Deus e confiar em seu cuidado.",
    l: ["“Ansiedade” traduz mérimna, a preocupação que divide e inquieta a mente.",
        "Pedro escreve a peregrinos dispersos no Ponto, Galácia, Capadócia, Ásia e Bitínia."] },
  { r: "2 Pedro 3:9", t: "O Senhor não retarda a sua promessa, ainda que alguns a têm por tardia; mas é longânimo para conosco, não querendo que alguns se percam, senão que todos venham a arrepender-se.",
    c: "Pedro responde aos que zombam da demora da vinda do Senhor, mostrando a paciência de Deus como oportunidade de arrependimento.",
    l: ["“Longânimo” traduz makrothyméo, suportar com paciência prolongada.",
        "A carta alerta contra falsos mestres que negavam a promessa da vinda de Cristo."] },
  { r: "1 João 1:9", t: "Se confessarmos os nossos pecados, ele é fiel e justo para nos perdoar os pecados, e nos purificar de toda a injustiça.",
    c: "João, escrevendo a comunidades cristãs, assegura o perdão a quem reconhece o pecado diante de Deus.",
    l: ["“Confessar” traduz homologéo, dizer o mesmo, concordar com Deus sobre o pecado.",
        "“Purificar” lembra os ritos de purificação do templo e da lei levítica."] },
  { r: "1 João 4:8", t: "Aquele que não ama não conhece a Deus; porque Deus é amor.",
    c: "João define a marca dos filhos de Deus pelo amor, em contraste com os falsos profetas e o anticristo.",
    l: ["“Conhece” traduz ginósko, conhecimento por relação, não mero saber teórico.",
        "“Deus é amor” afirma o caráter essencial de Deus, não uma emoção passageira."] },
  { r: "2 João 1:6", t: "E o amor é este: que andemos segundo os seus mandamentos. Este é o mandamento, como já desde o princípio ouvistes, que andeis nele.",
    c: "João escreve à senhora eleita e a seus filhos, exortando-os a viver no amor e na verdade e a evitar falsos mestres.",
    l: ["“Senhora eleita” pode designar uma igreja local ou uma mulher cristã específica.",
        "“Andar” é imagem hebraica para o modo de vida e a conduta."] },
  { r: "3 João 1:2", t: "Amado, desejo que te vá bem em todas as coisas, e que tenhas saúde, assim como bem vai a tua alma.",
    c: "João escreve ao amigo Gaio, estimando sua fidelidade e sua hospitalidade para com os missionários itinerantes.",
    l: ["“Saúde” e “alma” mostram a preocupação integral com o bem-estar físico e espiritual.",
        "A hospitalidade aos mestres itinerantes era dever central das igrejas primitivas."] },
  { r: "Judas 1:20", t: "Mas vós, amados, edificando-vos a vós mesmos na vossa santíssima fé, orando no Espírito Santo.",
    c: "Judas, irmão de Tiago, exorta os crentes a se guardarem dos falsos mestres e a permanecerem na fé.",
    l: ["“Edificando-vos” usa a imagem de construir um edifício sobre alicerce firme.",
        "Judas escreve a cristãos ameaçados por mestres que distorciam a graça em libertinagem."] },
  { r: "Apocalipse 3:20", t: "Eis que estou à porta, e bato; se alguém ouvir a minha voz, e abrir a porta, entrarei em sua casa, e com ele cearei, e ele comigo.",
    c: "Jesus dirige-se à igreja de Laodiceia, exortando-a a sair da mornidão e a abrir-lhe a porta.",
    l: ["Laodiceia era cidade rica, conhecida por seu comércio, suas roupas e um colírio medicinal.",
        "“Cear” refere-se à refeição da noite, ocasião de comunhão e intimidade no Oriente."] },
  { r: "Apocalipse 21:4", t: "E Deus limpará de seus olhos toda a lágrima; e não haverá mais morte, nem pranto, nem clamor, nem dor; porque já as primeiras coisas são passadas.",
    c: "João descreve a nova Jerusalém e o estado eterno, consolando as igrejas perseguidas da Ásia Menor.",
    l: ["A imagem retoma Isaías 25:8, onde Deus enxuga as lágrimas do seu povo.",
        "“Primeiras coisas” são a ordem presente, marcada por sofrimento e morte."] },
  { r: "Apocalipse 22:12", t: "E, eis que cedo venho, e o meu galardão está comigo, para dar a cada um segundo a sua obra.",
    c: "Antes do convite final, Cristo anuncia sua vinda próxima e a recompensa conforme as obras.",
    l: ["“Galardão” traduz misthós, salário ou recompensa pelo trabalho feito.",
        "“Cedo” traduz tachý, com rapidez, indicando a certeza da vinda."] },
  { r: "Apocalipse 22:13", t: "Eu sou o Alfa e o Ômega, o princípio e o fim, o primeiro e o derradeiro.",
    c: "No epílogo do livro, Cristo afirma sua eternidade e soberania sobre o começo e o fim de todas as coisas.",
    l: ["Alfa e ômega são a primeira e a última letra do alfabeto grego.",
        "O título afirma que Cristo abrange toda a história, do início ao fim."] },
];
